@import url("https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=swap");

:root {
    --cb-background: #f8fafc;
    --cb-surface: #ffffff;
    --cb-surface-secondary: #f1f5f9;
    --cb-surface-hover: #e2e8f0;
    --cb-border: #dbe3ef;
    --cb-divider: rgba(148, 163, 184, 0.24);
    --cb-text-primary: #071633;
    --cb-text-secondary: #334155;
    --cb-text-muted: #64748b;
    --cb-primary: #e11d2e;
    --cb-primary-hover: #be123c;
    --cb-success: #16a34a;
    --cb-warning: #f59e0b;
    --cb-danger: #dc2626;
    --cb-info: #1769e8;
    --cb-shadow: 0 10px 26px rgba(15, 23, 42, 0.05);
    --cb-overlay: rgba(15, 23, 42, 0.42);
    --cb-radius-card: 14px;
    --cb-radius-input: 10px;
    --cb-transition-duration: 220ms;
    --cb-transition-easing: ease;

    --cb-bg: var(--cb-background);
    --cb-bg-soft: var(--cb-surface-secondary);
    --cb-surface-soft: var(--cb-surface-secondary);
    --cb-surface-muted: var(--cb-surface-secondary);
    --cb-border-strong: var(--cb-divider);
    --cb-title: var(--cb-text-primary);
    --cb-text: var(--cb-text-secondary);
    --cb-muted: var(--cb-text-muted);
    --cb-primary-soft: color-mix(in srgb, var(--cb-primary) 10%, transparent);
    --cb-primary-border: color-mix(in srgb, var(--cb-primary) 18%, transparent);
    --cb-primary-hover-soft: color-mix(in srgb, var(--cb-primary-hover) 10%, transparent);
    --cb-accent: var(--cb-info);
    --cb-accent-soft: color-mix(in srgb, var(--cb-info) 10%, transparent);
    --cb-success-soft: color-mix(in srgb, var(--cb-success) 12%, transparent);
    --cb-danger-soft: color-mix(in srgb, var(--cb-danger) 12%, transparent);
    --cb-warning-soft: color-mix(in srgb, var(--cb-warning) 16%, transparent);

    --cb-theme-background: var(--cb-background);
    --cb-theme-surface: var(--cb-surface);
    --cb-theme-surface-secondary: var(--cb-surface-secondary);
    --cb-theme-surface-hover: var(--cb-surface-hover);
    --cb-theme-border: var(--cb-border);
    --cb-theme-divider: var(--cb-divider);
    --cb-theme-text-primary: var(--cb-text-primary);
    --cb-theme-text-secondary: var(--cb-text-secondary);
    --cb-theme-text-muted: var(--cb-text-muted);
    --cb-theme-primary: var(--cb-primary);
    --cb-theme-primary-hover: var(--cb-primary-hover);
    --cb-theme-success: var(--cb-success);
    --cb-theme-warning: var(--cb-warning);
    --cb-theme-danger: var(--cb-danger);
    --cb-theme-info: var(--cb-info);
    --cb-theme-shadow: var(--cb-shadow);

    --bg-main: var(--cb-background);
    --bg-panel: var(--cb-surface);
    --bg-card-top: var(--cb-surface-secondary);
    --bg-card-house: var(--cb-surface-secondary);
    --bg-card-soft: var(--cb-surface-secondary);
    --bg-input: var(--cb-surface);
    --border: var(--cb-border);
    --border-strong: var(--cb-divider);
    --border-soft: color-mix(in srgb, var(--cb-border) 60%, transparent);
    --text-main: var(--cb-text-primary);
    --text-soft: var(--cb-text-secondary);
    --text-muted: var(--cb-text-muted);
    --text-strong: var(--cb-text-primary);
    --brand-red: var(--cb-primary);
    --brand-red-soft: var(--cb-primary-hover);
    --brand-red-dark: var(--cb-primary-hover);
    --profit-green: var(--cb-success);
    --profit-green-soft: var(--cb-success-soft);
    --profit-green-border: color-mix(in srgb, var(--cb-success) 28%, transparent);
    --loss-red: var(--cb-danger);
    --loss-red-soft: var(--cb-danger-soft);
    --loss-red-border: color-mix(in srgb, var(--cb-danger) 30%, transparent);
    --shadow-soft: var(--cb-shadow);
    --shadow-card: var(--cb-shadow);
    --shadow-card-strong: var(--cb-shadow);
    --shadow-brand: var(--cb-shadow);
}

.dark-dashboard-shell.dashboard-shell {
    --cb-bg: var(--cb-theme-background);
    --cb-bg-soft: var(--cb-theme-surface-secondary);
    --cb-surface: var(--cb-theme-surface);
    --cb-surface-soft: var(--cb-theme-surface-secondary);
    --cb-surface-muted: var(--cb-theme-surface-secondary);
    --cb-border: var(--cb-theme-border);
    --cb-border-strong: var(--cb-theme-divider);
    --cb-text: var(--cb-theme-text-secondary);
    --cb-text-strong: var(--cb-theme-text-primary);
    --cb-muted: var(--cb-theme-text-muted);
    --cb-muted-strong: var(--cb-theme-text-muted);
    --cb-red: var(--cb-theme-danger);
    --cb-green: var(--cb-theme-success);
    --cb-blue: var(--cb-theme-info);
    color-scheme: dark;
    background:
        radial-gradient(circle at 10% 0%, color-mix(in srgb, var(--cb-theme-primary) 16%, transparent), transparent 30%),
        radial-gradient(circle at 90% 4%, color-mix(in srgb, var(--cb-theme-info) 14%, transparent), transparent 34%),
        linear-gradient(180deg, var(--cb-theme-background) 0%, color-mix(in srgb, var(--cb-theme-background) 84%, #000000) 100%) !important;
    color: var(--cb-theme-text-primary) !important;
}

.dark-dashboard-shell .dark-dashboard-sidebar {
    border-right: 1px solid var(--cb-theme-divider) !important;
    background:
        linear-gradient(180deg, color-mix(in srgb, var(--cb-theme-surface-secondary) 92%, #ffffff 8%), var(--cb-theme-surface-secondary)) !important;
    box-shadow: 12px 0 32px rgba(2, 6, 23, 0.3) !important;
}

.dark-dashboard-shell .dark-dashboard-sidebar .reference-brand-logo img {
    filter: drop-shadow(0 10px 20px rgba(2, 6, 23, 0.28)) !important;
}

.dark-dashboard-shell .dark-dashboard-sidebar .reference-sidebar-welcome,
.dark-dashboard-shell .dark-dashboard-sidebar .reference-nav-item {
    color: var(--cb-theme-text-secondary) !important;
}

.dark-dashboard-shell .dark-dashboard-sidebar .reference-nav-item.active,
.dark-dashboard-shell .dark-dashboard-sidebar .reference-nav-item:hover {
    border-color: var(--cb-primary-border) !important;
    background: color-mix(in srgb, var(--cb-theme-primary) 10%, var(--cb-theme-surface-secondary)) !important;
    color: var(--cb-theme-text-primary) !important;
}

.dark-dashboard-shell .dark-dashboard-sidebar .ref-icon {
    background: var(--cb-theme-background) !important;
    color: var(--cb-theme-text-secondary) !important;
}

.dark-dashboard-shell .dark-dashboard-sidebar .reference-sidebar-plan {
    border-color: var(--cb-theme-divider) !important;
    background: linear-gradient(180deg, var(--cb-theme-surface), var(--cb-theme-surface-secondary)) !important;
    box-shadow: var(--cb-theme-shadow) !important;
}

.dark-dashboard-shell .dark-dashboard-sidebar .reference-sidebar-plan strong,
.dark-dashboard-shell .dark-dashboard-sidebar .reference-sidebar-plan b {
    color: var(--cb-theme-text-primary) !important;
}

.dark-dashboard-shell .dark-dashboard-sidebar .reference-sidebar-plan span,
.dark-dashboard-shell .dark-dashboard-sidebar .reference-sidebar-plan p {
    color: var(--cb-theme-text-muted) !important;
}

.dark-dashboard-shell .dark-dashboard-main.dashboard-main {
    background: transparent !important;
    color: var(--cb-theme-text-primary) !important;
}

.dark-dashboard-shell .dark-dashboard-home,
.dark-dashboard-shell .dark-dashboard-panel,
.dark-dashboard-shell .dark-dashboard-home .cb-panel {
    border: 1px solid var(--cb-theme-border) !important;
    background: linear-gradient(180deg, color-mix(in srgb, var(--cb-theme-surface) 96%, #ffffff 4%), var(--cb-theme-surface-secondary)) !important;
    color: var(--cb-theme-text-primary) !important;
    box-shadow: var(--cb-theme-shadow) !important;
}

.dark-dashboard-shell .dark-dashboard-panel {
    border-radius: 16px !important;
}

.dark-dashboard-shell .dark-dashboard-home .cb-panel-header h2,
.dark-dashboard-shell .dark-dashboard-home .cb-panel h2,
.dark-dashboard-shell .dark-dashboard-home .cb-daily-row strong,
.dark-dashboard-shell .dark-dashboard-home .cb-donut-legend strong,
.dark-dashboard-shell .dark-dashboard-home .cb-quick-action-card strong {
    color: var(--cb-theme-text-primary) !important;
}

.dark-dashboard-shell .dark-dashboard-home .cb-panel-header p,
.dark-dashboard-shell .dark-dashboard-home .cb-panel span,
.dark-dashboard-shell .dark-dashboard-home .cb-panel small,
.dark-dashboard-shell .dark-dashboard-home .cb-daily-row span,
.dark-dashboard-shell .dark-dashboard-home .cb-quick-action-card > span,
.dark-dashboard-shell .dark-dashboard-home .cb-latest-head,
.dark-dashboard-shell .dark-dashboard-home .cb-latest-empty {
    color: var(--cb-theme-text-secondary) !important;
}

.dark-dashboard-shell .dark-filter-row {
    border-bottom: 1px solid var(--cb-theme-divider) !important;
}

.dark-dashboard-shell .dark-filter-field {
    color: var(--cb-theme-text-secondary) !important;
}

.dark-dashboard-shell .dark-filter-field span,
.dark-dashboard-shell .dark-filter-row .reference-period > span {
    color: var(--cb-theme-text-muted) !important;
}

.dark-dashboard-shell .dark-filter-field input,
.dark-dashboard-shell .dark-filter-field select,
.dark-dashboard-shell .dark-filter-row .reference-period select,
.dark-dashboard-shell .dark-filter-row .reference-selector-surface,
.dark-dashboard-shell .dark-topbar-profile,
.dark-dashboard-shell .dark-cancel-house-button {
    background: var(--cb-theme-surface-secondary) !important;
    border: 1px solid var(--cb-theme-border) !important;
    color: var(--cb-theme-text-primary) !important;
}

.dark-dashboard-shell .dark-filter-field input::placeholder {
    color: var(--cb-theme-text-muted) !important;
}

.dark-dashboard-shell .dark-filter-actions button {
    background: var(--cb-theme-surface-secondary) !important;
    border-color: var(--cb-theme-border) !important;
    color: var(--cb-theme-text-primary) !important;
}

.dark-dashboard-shell .dark-add-house-button {
    background: linear-gradient(180deg, var(--cb-theme-primary), var(--cb-theme-primary-hover)) !important;
    border-color: color-mix(in srgb, var(--cb-theme-primary) 42%, #000000) !important;
    color: #ffffff !important;
}

.dark-dashboard-shell .dark-topbar-profile strong {
    color: var(--cb-theme-text-primary) !important;
}

.dark-dashboard-shell .dark-topbar-profile small,
.dark-dashboard-shell .dark-filter-row .reference-selector-value {
    color: var(--cb-theme-text-muted) !important;
}

.dark-dashboard-shell .dark-dashboard-home .cb-area-chart,
.dark-dashboard-shell .dark-dashboard-home .cb-performance-chart,
.dark-dashboard-shell .dark-dashboard-home .cb-donut-chart,
.dark-dashboard-shell .dark-dashboard-home .cb-daily-row {
    background: transparent !important;
}

.dark-dashboard-shell .dark-dashboard-home .recharts-cartesian-grid line {
    stroke: var(--cb-theme-divider) !important;
}

.dark-dashboard-shell .dark-dashboard-home .recharts-text {
    fill: var(--cb-theme-text-muted) !important;
}

.dark-dashboard-shell .dark-dashboard-home .recharts-area-curve {
    stroke: var(--cb-theme-primary) !important;
}

.dark-dashboard-shell .dark-dashboard-home .recharts-area-area {
    opacity: 0.9 !important;
}

.dark-dashboard-shell .dark-dashboard-home .chart-tooltip {
    background: var(--cb-theme-surface) !important;
    border: 1px solid var(--cb-theme-border) !important;
    color: var(--cb-theme-text-primary) !important;
    box-shadow: var(--cb-theme-shadow) !important;
}

.dark-dashboard-shell .dark-dashboard-home .chart-tooltip span {
    color: var(--cb-theme-text-muted) !important;
}

.dark-dashboard-shell .dark-dashboard-home .chart-tooltip strong {
    color: var(--cb-theme-text-primary) !important;
}

.dark-dashboard-shell .dark-dashboard-home .cb-results-model-grid .cb-panel,
.dark-dashboard-shell .dark-dashboard-home .cb-daily-results-card {
    background: linear-gradient(180deg, var(--cb-theme-surface), var(--cb-theme-surface-secondary)) !important;
    border: 1px solid var(--cb-theme-border) !important;
}

.dark-dashboard-shell .dark-dashboard-home .cb-results-model-grid .cb-panel-header h2,
.dark-dashboard-shell .dark-dashboard-home .cb-results-model-grid .cb-panel-header p {
    color: var(--cb-theme-text-primary) !important;
}

.dark-dashboard-shell .dark-dashboard-home .cb-results-model-grid .cb-chart-mode-button,
.dark-dashboard-shell .dark-dashboard-home .cb-results-model-grid .cb-small-select,
.dark-dashboard-shell .dark-dashboard-home .cb-results-model-grid .cb-outline-button {
    background: var(--cb-theme-surface-secondary) !important;
    border-color: var(--cb-theme-border) !important;
    color: var(--cb-theme-text-primary) !important;
}

.dark-dashboard-shell .dark-dashboard-home .cb-results-model-grid .cb-daily-row strong.positive,
.dark-dashboard-shell .dark-dashboard-home .cb-results-model-grid .cb-daily-row i.positive {
    color: var(--cb-theme-success) !important;
}

.dark-dashboard-shell .dark-dashboard-home .cb-results-model-grid .cb-daily-row strong.negative,
.dark-dashboard-shell .dark-dashboard-home .cb-results-model-grid .cb-daily-row i.negative {
    color: var(--cb-theme-danger) !important;
}

.dark-dashboard-shell .dark-dashboard-home .cb-results-model-grid .cb-daily-row span,
.dark-dashboard-shell .dark-dashboard-home .cb-results-model-grid .cb-chart-axis-label,
.dark-dashboard-shell .dark-dashboard-home .cb-results-model-grid .cb-chart-axis-value {
    color: var(--cb-theme-text-muted) !important;
}


* {
    box-sizing: border-box;
}

html,
body,
#root {
    width: 100%;
    min-height: 100%;
    height: auto;
}

html,
body {
    overflow-x: hidden;
    overflow-y: auto;
}

body {
    margin: 0;
    font-family: "Poppins", Arial, Helvetica, sans-serif;
    background:
        radial-gradient(circle at 8% 0%, rgba(225, 29, 46, 0.18), transparent 30%),
        radial-gradient(circle at 88% 4%, rgba(56, 189, 248, 0.13), transparent 30%),
        radial-gradient(circle at 50% 100%, rgba(59, 130, 246, 0.10), transparent 34%),
        linear-gradient(180deg, #08111f 0%, #0b1626 45%, #07111f 100%);
    color: var(--text-main);
}

.app {
    width: 100%;
    max-width: none;
    min-height: 100vh;
    margin: 0;
    padding: 0;
}

.container {
    width: 100%;
    max-width: none;
    margin: 0 auto;
}

.dashboard-shell {
    width: 100%;
    min-height: 100vh;
    display: grid;
    grid-template-columns: 292px minmax(0, 1fr);
    gap: 30px;
    padding: 26px 30px 32px;
}

.dashboard-sidebar {
    position: fixed;
    top: 26px;
    left: 30px;
    width: 292px;
    height: calc(100vh - 52px);
    min-height: 640px;
    display: flex;
    flex-direction: column;
    gap: 28px;
    border: 1px solid rgba(128, 152, 186, 0.14);
    border-radius: 32px;
    padding: 24px 22px;
    background:
        radial-gradient(circle at 0% 0%, rgba(225, 29, 46, 0.065), transparent 36%),
        radial-gradient(circle at 100% 12%, rgba(56, 189, 248, 0.05), transparent 32%),
        linear-gradient(180deg, rgba(13, 24, 42, 0.9), rgba(7, 15, 28, 0.97));
    box-shadow:
        0 26px 68px rgba(0, 0, 0, 0.3),
        inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

.dashboard-sidebar-brand {
    display: flex;
    align-items: center;
    gap: 16px;
    min-width: 0;
    padding: 8px 6px 24px;
    border-bottom: 1px solid rgba(128, 152, 186, 0.16);
}

.dashboard-sidebar-logo {
    width: 68px;
    height: 68px;
    object-fit: contain;
    filter: drop-shadow(0 14px 24px rgba(0, 0, 0, 0.32));
}

.dashboard-sidebar-brand strong {
    display: block;
    color: #f7fbff;
    font-size: 1.06rem;
    font-weight: 900;
    line-height: 1.1;
}

.dashboard-sidebar-brand span {
    display: block;
    color: #8fa0b8;
    font-size: 0.74rem;
    font-weight: 750;
    line-height: 1.2;
}

.dashboard-sidebar-nav {
    display: grid;
    gap: 11px;
    padding-top: 4px;
}

.dashboard-sidebar-link {
    min-height: 48px;
    display: flex;
    align-items: center;
    gap: 11px;
    border: 1px solid transparent;
    border-radius: 18px;
    padding: 0 15px;
    background: transparent;
    color: #9fb0c8;
    font: inherit;
    font-size: 0.88rem;
    font-weight: 800;
    text-align: left;
    cursor: default;
    transition: border-color 0.18s ease, background 0.18s ease, color 0.18s ease, transform 0.18s ease;
}

.dashboard-sidebar-link span {
    width: 28px;
    height: 28px;
    display: inline-grid;
    place-items: center;
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.045);
    color: #c7d3e5;
    font-size: 0.72rem;
}

.dashboard-sidebar-link.active,
.dashboard-sidebar-link:hover {
    border-color: rgba(248, 113, 113, 0.18);
    background:
        radial-gradient(circle at 0% 50%, rgba(248, 113, 113, 0.12), transparent 48%),
        linear-gradient(180deg, rgba(255, 255, 255, 0.06), rgba(255, 255, 255, 0.024));
    color: #f7fbff;
    transform: translateX(2px);
}

.dashboard-sidebar-link.active span,
.dashboard-sidebar-link:hover span {
    background: rgba(225, 29, 46, 0.14);
    color: #fecdd3;
}

.dashboard-sidebar-upgrade {
    margin-top: auto;
    display: grid;
    gap: 11px;
    border: 1px solid rgba(248, 113, 113, 0.16);
    border-radius: 26px;
    padding: 18px;
    background:
        radial-gradient(circle at 0% 0%, rgba(248, 113, 113, 0.13), transparent 42%),
        linear-gradient(180deg, rgba(255, 255, 255, 0.06), rgba(255, 255, 255, 0.022));
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.dashboard-sidebar-upgrade span {
    color: #fecdd3;
    font-size: 0.72rem;
    font-weight: 900;
}

.dashboard-sidebar-upgrade strong {
    color: #f7fbff;
    font-size: 0.9rem;
    line-height: 1.25;
}

.dashboard-sidebar-upgrade button {
    min-height: 34px;
    border: 1px solid rgba(248, 113, 113, 0.32);
    border-radius: 999px;
    background: linear-gradient(180deg, #f43f5e, #d91f2e);
    color: #ffffff;
    font: inherit;
    font-size: 0.78rem;
    font-weight: 900;
    cursor: default;
}

.dashboard-main {
    min-width: 0;
    grid-column: 2;
    padding: 4px 0 0;
}

.page-header {
    margin-bottom: -30px;
}

.page-header h1 {
    margin: 0;
}

.dashboard-topbar {
    position: relative;
    overflow: hidden;
    min-height: 112px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 18px;
    margin: 0 0 24px;
    padding: 22px 24px;
    border: 1px solid rgba(128, 152, 186, 0.24);
    border-radius: 28px;
    background:
        radial-gradient(circle at 8% 0%, rgba(225, 29, 46, 0.11), transparent 34%),
        radial-gradient(circle at 92% 0%, rgba(56, 189, 248, 0.08), transparent 32%),
        linear-gradient(180deg, rgba(19, 32, 52, 0.9), rgba(9, 20, 36, 0.9));
    box-shadow:
        0 24px 58px rgba(0, 0, 0, 0.28),
        inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.dashboard-topbar::before {
    content: "";
    position: absolute;
    inset: 0;
    pointer-events: none;
    background:
        linear-gradient(90deg, rgba(255, 255, 255, 0.07), transparent 30%),
        linear-gradient(180deg, rgba(255, 255, 255, 0.045), transparent 58%);
    opacity: 0.72;
}

.dashboard-topbar-brand {
    position: relative;
    z-index: 1;
    min-width: 0;
    display: flex;
    align-items: flex-start;
    gap: 12px;
}

.dashboard-heading-copy {
    display: grid;
    gap: 8px;
    min-width: 0;
}

.dashboard-heading-copy h1 {
    margin: 0;
    color: #f7fbff;
    font-size: clamp(2rem, 2.6vw, 2.75rem);
    line-height: 1.05;
    font-weight: 900;
    letter-spacing: 0;
}

.dashboard-heading-copy p {
    margin: 0;
    color: #9fb0c8;
    font-size: 0.96rem;
    font-weight: 700;
    line-height: 1.35;
}

.dashboard-topbar-logo {
    width: auto;
    height: 56px;
    display: block;
    object-fit: contain;
    transform: translateX(-6px);
    filter: drop-shadow(0 12px 22px rgba(0, 0, 0, 0.28));
}

.dashboard-section-label {
    min-height: 28px;
    padding: 0 11px;
    border: 1px solid rgba(148, 173, 211, 0.18);
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.055);
    position: relative;
    display: inline-flex;
    align-items: center;
    color: #c7d3e5;
    font-size: 0.86rem;
    font-weight: 800;
    white-space: nowrap;
}

.dashboard-section-label::before {
    content: "";
    width: 6px;
    height: 6px;
    margin-right: 8px;
    border-radius: 999px;
    background: var(--brand-red);
    box-shadow: 0 0 16px rgba(225, 29, 46, 0.55);
}

.dashboard-topbar-actions {
    position: relative;
    z-index: 2;
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 10px;
}

.dashboard-account-menu-wrap {
    position: relative;
}

.dashboard-account-button {
    min-height: 52px;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto auto auto;
    align-items: center;
    gap: 12px;
    border: 1px solid rgba(148, 173, 211, 0.26);
    border-radius: 999px;
    padding: 6px 10px 6px 16px;
    background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.09), rgba(255, 255, 255, 0.035));
    color: #f7fbff;
    font: inherit;
    cursor: pointer;
    box-shadow:
        0 12px 26px rgba(0, 0, 0, 0.22),
        inset 0 1px 0 rgba(255, 255, 255, 0.075);
    transition: transform 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
}

.dashboard-account-button:hover {
    transform: translateY(-1px);
    border-color: rgba(248, 113, 113, 0.34);
    background:
        linear-gradient(180deg, rgba(248, 113, 113, 0.12), rgba(255, 255, 255, 0.04));
    box-shadow:
        0 16px 32px rgba(0, 0, 0, 0.28),
        inset 0 1px 0 rgba(255, 255, 255, 0.09);
}

.dashboard-account-button:focus-visible {
    outline: 3px solid rgba(225, 29, 46, 0.16);
    outline-offset: 3px;
}

.dashboard-account-avatar {
    width: 38px;
    height: 38px;
    display: inline-grid;
    place-items: center;
    border-radius: 999px;
    background: linear-gradient(135deg, var(--brand-red), var(--brand-red-dark));
    color: #ffffff;
    font-size: 0.78rem;
    font-weight: 900;
    letter-spacing: 0.02em;
    box-shadow: 0 8px 16px rgba(185, 28, 28, 0.18);
}

.dashboard-account-copy {
    min-width: 0;
    display: grid;
    gap: 1px;
    text-align: left;
}

.dashboard-account-copy strong {
    max-width: 210px;
    overflow: hidden;
    color: #f7fbff;
    font-size: 0.88rem;
    font-weight: 900;
    line-height: 1.1;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.dashboard-account-copy span {
    color: #9fb0c8;
    font-size: 0.7rem;
    font-weight: 800;
    line-height: 1.1;
}

.dashboard-account-plan {
    min-height: 28px;
    display: inline-flex;
    align-items: center;
    border: 1px solid rgba(248, 113, 113, 0.22);
    border-radius: 999px;
    padding: 0 11px;
    background: rgba(225, 29, 46, 0.12);
    color: #fecdd3 !important;
    font-size: 0.72rem !important;
    font-weight: 900 !important;
    white-space: nowrap;
}

.dashboard-account-caret {
    color: #c7d3e5;
    font-size: 0.76rem;
}

.dashboard-account-menu {
    position: absolute;
    top: calc(100% + 8px);
    right: 0;
    z-index: 100000;
    min-width: 150px;
    display: grid;
    gap: 4px;
    border: 1px solid rgba(148, 173, 211, 0.26);
    border-radius: 14px;
    padding: 6px;
    background: rgba(12, 23, 39, 0.98);
    box-shadow: 0 22px 50px rgba(0, 0, 0, 0.36);
}

.dashboard-account-menu button {
    min-height: 34px;
    border: 0;
    border-radius: 10px;
    padding: 0 10px;
    background: transparent;
    color: #dbe6f5;
    font: inherit;
    font-size: 0.8rem;
    font-weight: 800;
    text-align: left;
    cursor: pointer;
}

.dashboard-account-menu button:hover {
    background: rgba(248, 113, 113, 0.12);
    color: #fecdd3;
}

.dashboard-deletion-alert {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    margin: -6px 0 18px;
    border: 1px solid rgba(217, 119, 6, 0.24);
    border-radius: 14px;
    padding: 9px 12px;
    background: linear-gradient(180deg, #fffbeb, #fff7ed);
    color: #92400e;
    box-shadow: 0 10px 24px rgba(146, 64, 14, 0.06);
}

.dashboard-deletion-alert span {
    min-width: 0;
    font-size: 0.78rem;
    font-weight: 850;
    line-height: 1.35;
}

.dashboard-deletion-alert button {
    flex: 0 0 auto;
    min-height: 30px;
    border: 1px solid rgba(180, 83, 9, 0.24);
    border-radius: 999px;
    padding: 0 12px;
    background: #ffffff;
    color: #92400e;
    font: inherit;
    font-size: 0.74rem;
    font-weight: 900;
    cursor: pointer;
    transition: transform 0.18s ease, border-color 0.18s ease, background 0.18s ease;
}

.dashboard-deletion-alert button:hover {
    transform: translateY(-1px);
    border-color: rgba(180, 83, 9, 0.38);
    background: #fffaf0;
}

.dashboard-deletion-alert button:disabled {
    cursor: not-allowed;
    opacity: 0.72;
    transform: none;
}

.profile-modal-overlay {
    position: fixed;
    inset: 0;
    z-index: 120;
    display: grid;
    place-items: center;
    overflow: hidden;
    padding: 24px;
    background: rgba(15, 23, 42, 0.42);
    backdrop-filter: blur(4px);
    overscroll-behavior: contain;
}

.profile-modal {
    position: relative;
    width: min(440px, 100%);
    max-height: calc(100vh - 48px);
    display: grid;
    gap: 18px;
    overflow-y: auto;
    overscroll-behavior: contain;
    border: 1px solid var(--border-soft);
    border-radius: 22px;
    padding: 24px;
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.96));
    box-shadow: 0 30px 80px rgba(15, 23, 42, 0.24), 0 1px 0 rgba(255, 255, 255, 0.82) inset;
    scrollbar-gutter: stable;
}

.profile-modal-close {
    position: absolute;
    top: 12px;
    right: 12px;
    width: 32px;
    height: 32px;
    display: inline-grid;
    place-items: center;
    border: 1px solid rgba(148, 163, 184, 0.28);
    border-radius: 999px;
    background: #ffffff;
    color: #64748b;
    font: inherit;
    font-size: 1.2rem;
    font-weight: 800;
    line-height: 1;
    cursor: pointer;
}

.profile-modal-close:hover {
    color: var(--brand-red);
    background: #fff7f7;
}

.profile-modal-header {
    display: flex;
    align-items: center;
    gap: 12px;
    padding-right: 34px;
}

.profile-modal-avatar {
    width: 44px;
    height: 44px;
    font-size: 0.9rem;
}

.profile-modal-header h2 {
    margin: 0;
    color: #0f172a;
    font-size: 1.18rem;
    line-height: 1.2;
}

.profile-modal-header p {
    margin: 5px 0 0;
    color: #64748b;
    font-size: 0.84rem;
    font-weight: 600;
    line-height: 1.35;
}

.profile-details {
    display: grid;
    gap: 10px;
    margin: 0;
}

.profile-details div {
    border: 1px solid rgba(148, 163, 184, 0.22);
    border-radius: 14px;
    padding: 11px 12px;
    background: linear-gradient(180deg, #ffffff, #f8fafc);
}

.profile-details dt {
    color: #64748b;
    font-size: 0.72rem;
    font-weight: 900;
    text-transform: uppercase;
}

.profile-details dd {
    margin: 4px 0 0;
    color: #0f172a;
    font-size: 0.92rem;
    font-weight: 800;
    overflow-wrap: anywhere;
}

.profile-form {
    display: grid;
    gap: 12px;
}

.profile-form-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
}

.profile-form label {
    display: grid;
    gap: 5px;
    color: #0f172a;
    font-size: 0.78rem;
    font-weight: 900;
}

.profile-form input {
    width: 100%;
    min-height: 40px;
    border: 1px solid rgba(148, 163, 184, 0.3);
    border-radius: 12px;
    padding: 0 12px;
    background: #ffffff;
    color: #0f172a;
    font: inherit;
    font-size: 0.86rem;
    outline: none;
    transition: border-color 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
}

.profile-form input:focus {
    border-color: rgba(225, 29, 46, 0.42);
    box-shadow: 0 0 0 4px rgba(225, 29, 46, 0.11);
}

.profile-form input:disabled {
    cursor: not-allowed;
    opacity: 0.74;
}

.profile-field-note {
    color: #64748b;
    font-size: 0.72rem;
    font-weight: 700;
    line-height: 1.3;
}

.profile-security-box {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    border: 1px solid rgba(148, 163, 184, 0.22);
    border-radius: 14px;
    padding: 12px;
    background: linear-gradient(180deg, #ffffff, #f8fafc);
}

.profile-security-actions {
    display: flex;
    flex-wrap: wrap;
    justify-content: flex-end;
    gap: 8px;
}

.profile-security-box strong {
    display: block;
    color: #0f172a;
    font-size: 0.86rem;
    font-weight: 900;
}

.profile-security-box p {
    margin: 4px 0 0;
    color: #64748b;
    font-size: 0.76rem;
    font-weight: 600;
    line-height: 1.35;
}

.profile-security-panel {
    display: grid;
    gap: 12px;
    border: 1px solid rgba(148, 163, 184, 0.22);
    border-radius: 14px;
    padding: 12px;
    background: #ffffff;
}

.profile-security-session-box {
    display: grid;
    gap: 12px;
    border: 1px solid rgba(148, 163, 184, 0.22);
    border-radius: 14px;
    padding: 12px;
    background: linear-gradient(180deg, #ffffff, #f8fafc);
}

.profile-accordion-trigger {
    width: 100%;
    text-align: left;
    font: inherit;
    cursor: pointer;
}

.profile-accordion-trigger .profile-security-panel-header {
    flex: 1 1 auto;
}

.profile-accordion-caret {
    width: 28px;
    height: 28px;
    display: inline-grid;
    flex: 0 0 auto;
    place-items: center;
    border: 1px solid rgba(148, 163, 184, 0.24);
    border-radius: 999px;
    background: #ffffff;
    transition: transform 0.18s ease, border-color 0.18s ease, background 0.18s ease;
}

.profile-accordion-caret::before {
    content: "";
    width: 7px;
    height: 7px;
    border-right: 2px solid #64748b;
    border-bottom: 2px solid #64748b;
    transform: translateY(-1px) rotate(45deg);
    transition: transform 0.18s ease, border-color 0.18s ease;
}

.profile-accordion-trigger[aria-expanded="true"] .profile-accordion-caret {
    border-color: rgba(225, 29, 46, 0.24);
    background: #fff7f7;
    transform: rotate(180deg);
}

.profile-accordion-trigger[aria-expanded="true"] .profile-accordion-caret::before {
    border-color: var(--brand-red-dark);
}

.profile-accordion-content {
    display: grid;
    grid-template-rows: 0fr;
    opacity: 0;
    overflow: hidden;
    visibility: hidden;
    transition: grid-template-rows 0.22s ease, opacity 0.18s ease, visibility 0s linear 0.22s;
}

.profile-accordion-content.is-open {
    grid-template-rows: 1fr;
    opacity: 1;
    visibility: visible;
    transition-delay: 0s;
}

.profile-accordion-inner {
    min-height: 0;
    display: grid;
    gap: 12px;
}

.profile-session-details {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
    margin: 0;
}

.profile-session-details div {
    min-width: 0;
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 12px;
    padding: 10px;
    background: #ffffff;
}

.profile-session-details dt {
    margin: 0 0 4px;
    color: #64748b;
    font-size: 0.72rem;
    font-weight: 800;
}

.profile-session-details dd {
    margin: 0;
    color: #0f172a;
    font-size: 0.82rem;
    font-weight: 800;
    word-break: break-word;
}

.profile-security-panel-header strong {
    display: block;
    color: #0f172a;
    font-size: 0.86rem;
    font-weight: 900;
}

.profile-security-panel-header p {
    margin: 4px 0 0;
    color: #64748b;
    font-size: 0.76rem;
    font-weight: 600;
    line-height: 1.35;
}

.profile-security-panel-actions {
    display: flex;
    justify-content: flex-end;
    gap: 8px;
}

.profile-password-box {
    display: grid;
    gap: 8px;
    border: 1px solid rgba(148, 163, 184, 0.2);
    border-radius: 12px;
    padding: 10px;
    background: #f8fafc;
}

.profile-password-title,
.profile-password-strong {
    color: #0f172a;
    font-size: 0.76rem;
    font-weight: 900;
}

.profile-password-strong {
    color: #15803d;
}

.profile-password-requirements {
    display: flex;
    flex-wrap: wrap;
    gap: 7px;
    margin: 0;
    padding: 0;
    list-style: none;
}

.profile-password-requirements li {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    color: #64748b;
    font-size: 0.72rem;
    font-weight: 800;
}

.profile-password-requirements span {
    color: #94a3b8;
    font-weight: 900;
}

.profile-password-requirements li.is-valid {
    color: #15803d;
}

.profile-password-requirements li.is-valid span {
    color: #16a34a;
}

.profile-inline-message {
    margin: -2px 0 0;
    border: 1px solid rgba(148, 163, 184, 0.2);
    border-radius: 12px;
    padding: 8px 10px;
    background: #ffffff;
    color: #64748b;
    font-size: 0.78rem;
    font-weight: 700;
    line-height: 1.35;
}

.profile-inline-message-success {
    border-color: rgba(22, 163, 74, 0.22);
    background: #f0fdf4;
    color: #166534;
}

.profile-inline-message-error {
    border-color: rgba(220, 38, 38, 0.22);
    background: #fff7f7;
    color: #991b1b;
}

.profile-actions {
    display: flex;
    justify-content: flex-end;
    gap: 8px;
}

.profile-primary-button,
.profile-secondary-button {
    min-height: 36px;
    border-radius: 999px;
    padding: 0 14px;
    font: inherit;
    font-size: 0.8rem;
    font-weight: 900;
    cursor: pointer;
    transition: transform 0.18s ease, border-color 0.18s ease, background 0.18s ease, box-shadow 0.18s ease;
}

.profile-primary-button {
    border: 1px solid rgba(225, 29, 46, 0.34);
    background: linear-gradient(135deg, var(--brand-red) 0%, var(--brand-red-dark) 100%);
    color: #ffffff;
    box-shadow: 0 12px 24px rgba(185, 28, 28, 0.18);
}

.profile-secondary-button {
    border: 1px solid rgba(148, 163, 184, 0.34);
    background: #ffffff;
    color: #475569;
}

.profile-danger-button {
    min-height: 36px;
    border: 1px solid rgba(220, 38, 38, 0.24);
    border-radius: 999px;
    padding: 0 14px;
    background: #ffffff;
    color: #b91c1c;
    font: inherit;
    font-size: 0.8rem;
    font-weight: 900;
    cursor: pointer;
    transition: transform 0.18s ease, border-color 0.18s ease, background 0.18s ease, box-shadow 0.18s ease;
}

.profile-danger-button:hover {
    transform: translateY(-1px);
    border-color: rgba(220, 38, 38, 0.36);
    background: #fef2f2;
}

.profile-danger-button-solid {
    border-color: rgba(220, 38, 38, 0.78);
    background: #dc2626;
    color: #ffffff;
    box-shadow: 0 12px 24px rgba(220, 38, 38, 0.16);
}

.profile-danger-button-solid:hover {
    background: #b91c1c;
}

.profile-primary-button:hover,
.profile-secondary-button:hover {
    transform: translateY(-1px);
}

.profile-secondary-button:hover {
    border-color: rgba(225, 29, 46, 0.24);
    color: var(--brand-red-dark);
    background: #fff7f7;
}

.profile-primary-button:disabled,
.profile-secondary-button:disabled,
.profile-danger-button:disabled {
    cursor: not-allowed;
    opacity: 0.72;
    transform: none;
}

.profile-security-panel-danger {
    gap: 10px;
    border-color: rgba(220, 38, 38, 0.22);
    background: #fffafa;
}

.profile-form .delete-confirm-inline {
    display: flex;
    align-items: center;
    gap: 8px;
    margin: 12px 0;
    color: #7f1d1d;
    font-size: 0.78rem;
    font-weight: 850;
}

.profile-form .delete-confirm-inline input {
    flex: 0 0 auto;
    width: auto;
    min-width: 0;
    min-height: 0;
    height: auto;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: 0;
    accent-color: #dc2626;
}

.profile-form .delete-confirm-inline span {
    line-height: 1.3;
}

.profile-deletion-notice {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    border: 1px solid rgba(220, 38, 38, 0.2);
    border-radius: 14px;
    padding: 12px;
    background: #fff7f7;
}

.profile-deletion-notice strong {
    display: block;
    color: #991b1b;
    font-size: 0.82rem;
    font-weight: 900;
    line-height: 1.3;
}

.profile-deletion-notice p {
    margin: 4px 0 0;
    color: #7f1d1d;
    font-size: 0.74rem;
    font-weight: 650;
    line-height: 1.35;
}

@media (max-width: 560px) {
    .profile-modal-overlay {
        padding: 14px;
    }

    .profile-modal {
        max-height: calc(100vh - 28px);
    }

    .profile-form-grid,
    .profile-security-box,
    .profile-security-session-box,
    .profile-session-details,
    .profile-deletion-notice,
    .profile-security-panel-actions,
    .profile-actions {
        grid-template-columns: 1fr;
        flex-direction: column;
        align-items: stretch;
    }

    .profile-security-actions {
        justify-content: stretch;
    }

    .profile-accordion-trigger {
        flex-direction: row;
        align-items: center;
    }

    .profile-security-actions .profile-secondary-button,
    .profile-security-actions .profile-danger-button,
    .profile-security-panel-actions .profile-primary-button,
    .profile-security-panel-actions .profile-secondary-button,
    .profile-security-panel-actions .profile-danger-button,
    .profile-deletion-notice .profile-secondary-button,
    .profile-actions .profile-primary-button,
    .profile-actions .profile-secondary-button {
        width: 100%;
    }

}

.brand-light {
    color: var(--brand-red);
}

.brand-accent {
    color: #111111;
}

.panel {
    background:
        radial-gradient(circle at 0% 0%, rgba(148, 173, 211, 0.07), transparent 38%),
        linear-gradient(180deg, rgba(17, 29, 48, 0.88) 0%, rgba(11, 22, 39, 0.92) 100%);
    border: 1px solid rgba(128, 152, 186, 0.2);
    border-radius: 26px;
    padding: 16px;
    box-shadow:
        0 24px 64px rgba(0, 0, 0, 0.28),
        inset 0 1px 0 rgba(255, 255, 255, 0.055);
}

.top-panel {
    margin-bottom: 24px;
    overflow: visible;
    padding: 22px;
    border-radius: 30px;
}

/* ===== LANDING ===== */

.landing-page {
    --landing-background:
        radial-gradient(circle at 12% 8%, rgba(225, 29, 46, 0.10), transparent 26%),
        linear-gradient(180deg, #f7f9fc 0%, #eef3f8 100%);
    --landing-surface: rgba(255, 255, 255, 0.9);
    --landing-surface-strong: rgba(255, 255, 255, 0.96);
    --landing-surface-soft: rgba(255, 255, 255, 0.72);
    --landing-preview-surface: linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(248, 250, 252, 0.92));
    --landing-preview-surface-hover: linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.96));
    --landing-chart-surface: linear-gradient(180deg, rgba(248, 250, 252, 0.98), rgba(255, 255, 255, 0.94));
    --landing-chart-inner: rgba(255, 255, 255, 0.74);
    --landing-text: #0f172a;
    --landing-muted: #64748b;
    --landing-border: rgba(216, 225, 236, 0.9);
    --landing-border-strong: rgba(188, 202, 221, 0.92);
    --landing-accent: var(--brand-red);
    --landing-accent-dark: var(--brand-red-dark);
    --landing-shadow-soft: 0 12px 28px rgba(15, 23, 42, 0.05);
    --landing-shadow-hover: 0 18px 34px rgba(15, 23, 42, 0.075);
    --landing-preview-shadow: 0 20px 48px rgba(15, 23, 42, 0.10), 0 1px 0 rgba(255, 255, 255, 0.72) inset;
    --landing-preview-shadow-hover: 0 26px 62px rgba(15, 23, 42, 0.13), 0 1px 0 rgba(255, 255, 255, 0.82) inset;
    --landing-axis: rgba(71, 85, 105, 0.84);
    --landing-grid: rgba(148, 163, 184, 0.18);
    --landing-positive: #15803d;
    min-height: 100vh;
    background: var(--landing-background);
    color: var(--landing-text);
    transition: background 0.24s ease, color 0.24s ease;
}

.landing-page[data-theme="dark"] {
    --landing-background:
        radial-gradient(circle at 14% 6%, rgba(225, 29, 46, 0.16), transparent 28%),
        linear-gradient(180deg, #101622 0%, #0b111b 100%);
    --landing-surface: rgba(20, 28, 42, 0.9);
    --landing-surface-strong: rgba(24, 33, 49, 0.96);
    --landing-surface-soft: rgba(20, 28, 42, 0.58);
    --landing-preview-surface: linear-gradient(180deg, rgba(22, 31, 47, 0.98), rgba(15, 23, 36, 0.94));
    --landing-preview-surface-hover: linear-gradient(180deg, rgba(26, 37, 56, 0.99), rgba(17, 26, 40, 0.97));
    --landing-chart-surface: linear-gradient(180deg, rgba(15, 23, 36, 0.98), rgba(20, 28, 42, 0.94));
    --landing-chart-inner: rgba(11, 17, 27, 0.48);
    --landing-text: #f8fafc;
    --landing-muted: #aeb9c9;
    --landing-border: rgba(111, 126, 149, 0.28);
    --landing-border-strong: rgba(148, 163, 184, 0.34);
    --landing-shadow-soft: 0 14px 32px rgba(0, 0, 0, 0.22);
    --landing-shadow-hover: 0 20px 42px rgba(0, 0, 0, 0.30);
    --landing-preview-shadow: 0 24px 58px rgba(0, 0, 0, 0.32), 0 1px 0 rgba(255, 255, 255, 0.05) inset;
    --landing-preview-shadow-hover: 0 30px 72px rgba(0, 0, 0, 0.42), 0 1px 0 rgba(255, 255, 255, 0.07) inset;
    --landing-axis: rgba(203, 213, 225, 0.74);
    --landing-grid: rgba(148, 163, 184, 0.16);
    --landing-positive: #4ade80;
}

.landing-shell {
    width: min(1080px, calc(100% - 44px));
    min-height: 100vh;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
}

.landing-header {
    min-height: 54px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 24px;
    margin-top: -8px;
    margin-bottom: 12px;
