}

.reference-ticket-details dl {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 12px;
    margin: 0;
}

.reference-ticket-details dt {
    color: #52637d;
    font-size: 0.72rem;
    font-weight: 850;
}

.reference-ticket-details dd {
    margin: 4px 0 0;
    color: #071332;
    font-weight: 900;
}

.reference-settings-panel {
    padding: 28px !important;
}

.submenu-account-page {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}

.submenu-account-page .submenu-page-header {
    grid-column: 1 / -1;
}

.reference-settings-panel dl {
    display: grid !important;
    gap: 0 !important;
    margin: 18px 0 22px !important;
}

.reference-settings-panel dl div {
    display: grid !important;
    grid-template-columns: 48px minmax(130px, 0.7fr) minmax(0, 1fr) !important;
    align-items: center !important;
    gap: 18px !important;
    border-bottom: 1px solid #e4ebf4 !important;
