    height: 48px;
    border-radius: 10px;
    background: #f1f4f8;
}

.reference-settings-panel dt {
    color: #42536d !important;
    font-size: 0.84rem !important;
    font-weight: 850 !important;
}

.reference-settings-panel dd {
    margin: 0 !important;
    color: #071332 !important;
    font-size: 0.88rem !important;
    font-weight: 900 !important;
}

.reference-settings-panel p {
    color: #40536f !important;
    font-weight: 650 !important;
}

.reference-settings-panel hr {
    border: 0;
    border-top: 1px solid #e4ebf4;
    margin: 22px 0;
}

.reports-page .reports-section {
    gap: 22px !important;
}

.reports-page-heading {
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important;
    gap: 18px !important;
}

.reports-page-heading::before {
    content: "";
    width: 58px;
    height: 58px;
    flex: 0 0 auto;
    border-radius: 14px;
    background: #ffe8ec;
}

.reports-page-heading h2 {
    font-size: 1.7rem !important;
}

.reports-header-tools {
    display: grid !important;
    grid-template-columns: 1fr auto auto !important;
    gap: 18px !important;
    align-items: end !important;
    border: 1px solid rgba(210, 220, 234, 0.9);
    border-radius: 14px;
    padding: 20px;
    background: #ffffff;
}

.reports-tabs {
    background: #f7f9fd !important;
    border-color: #dce4ef !important;
}

.reports-tabs button {
    color: #40536f !important;
}

.reports-tabs button.active {
    background: #ef1734 !important;
    color: #ffffff !important;
}

.reports-period-controls {
    display: grid !important;
    grid-template-columns: repeat(2, minmax(150px, 1fr)) !important;
    width: auto !important;
    transform: none !important;
}

.reports-metric-group {
    padding: 0 !important;
    border: 0 !important;
    background: transparent !important;
    box-shadow: none !important;
}

.reports-metric-group h3 {
    margin-bottom: 10px !important;
}

.reports-advanced-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr)) !important;
}

.reports-advanced-card {
    min-height: 118px !important;
    border: 1px solid #dce4ef !important;
    border-radius: 14px !important;
    background: #ffffff !important;
}

@media (max-width: 980px) {
    .submenu-page,
    .reports-page {
        gap: 16px;
    }

    .reference-local-filters,
    .reference-panel-form,
    .submenu-form,
    .submenu-metric-grid.four,
    .submenu-metric-grid.five,
    .reference-kpi-row,
    .submenu-account-page,
    .reports-header-tools,
    .reports-period-controls,
    .reports-advanced-grid {
        grid-template-columns: 1fr !important;
    }

    .reference-panel-form label.wide,
    .reference-panel-form .wide,
    .submenu-form label.wide {
        grid-column: auto;
    }

    .submenu-card,
    .reference-functional-panel,
    .reports-section,
    .reference-panel-list {
        padding: 18px !important;
    }

    .submenu-summary-box > div,
    .reference-ticket-details dl {
        grid-template-columns: 1fr !important;
    }
}

.landing-top-button {
    display: inline-flex;
