    font-size: 0.89rem;
    line-height: 1.45;
}

.auth-form {
    display: grid;
    gap: 9px;
}

.auth-name-row {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
}

.auth-form label {
    display: grid;
