    opacity: 0.7;
    transform: none;
}

.auth-resend-button {
    width: 100%;
    min-height: 36px;
    margin-top: -2px;
}

.auth-text-button {
    width: fit-content;
    border: 0;
    padding: 0;
    background: transparent;
    color: var(--landing-muted);
    font: inherit;
    font-size: 0.78rem;
    font-weight: 800;
    cursor: pointer;
}

.auth-text-button:hover {
    color: var(--landing-accent);
    text-decoration: underline;
}

.auth-text-button:disabled {
    cursor: not-allowed;
    opacity: 0.64;
}

.auth-message {
