    color: #991b1b;
}

.auth-message-success {
    border: 1px solid rgba(21, 128, 61, 0.22);
    background: rgba(21, 128, 61, 0.08);
    color: #166534;
}

.auth-message-info {
    border: 1px solid rgba(37, 99, 235, 0.2);
    background: rgba(37, 99, 235, 0.08);
    color: #1d4ed8;
}

.auth-submit-button {
    width: 100%;
    min-height: 44px;
    margin-top: 3px;
    border: 1px solid rgba(225, 29, 46, 0.34);
    border-radius: 999px;
    background: linear-gradient(135deg, var(--landing-accent) 0%, var(--landing-accent-dark) 100%);
    color: #ffffff;
    font: inherit;
    font-size: 0.9rem;
    font-weight: 800;
    cursor: pointer;
    box-shadow: 0 16px 32px rgba(185, 28, 28, 0.22);
    transition: transform 0.18s ease, box-shadow 0.18s ease, filter 0.18s ease;
}

.auth-submit-button:hover {
    transform: translateY(-1px);
    filter: saturate(1.04);
    box-shadow: 0 20px 40px rgba(185, 28, 28, 0.29);
}

.auth-submit-button:disabled {
    cursor: not-allowed;
    opacity: 0.72;
    transform: none;
    box-shadow: 0 10px 22px rgba(185, 28, 28, 0.16);
}

.auth-route-loading {
    min-height: 100vh;
    display: grid;
    place-items: center;
    color: var(--text-soft);
    font-family: "Poppins", Arial, Helvetica, sans-serif;
    font-weight: 800;
}

.route-error-fallback {
    align-content: center;
    gap: 12px;
    padding: 24px;
    text-align: center;
}

.route-error-fallback p {
    margin: 0;
}

.route-error-fallback button {
    justify-self: center;
    border: 0;
    border-radius: 10px;
    padding: 10px 16px;
    background: #ff243d;
    color: #fff;
    font: inherit;
    cursor: pointer;
}

.reports-page {
    display: grid;
    gap: 18px;
}

.reports-header,
.reports-filters,
.reports-house-selector,
.reports-section {
    border: 1px solid var(--border-soft);
    border-radius: 14px;
    background: var(--bg-panel);
    box-shadow: var(--shadow-soft);
}

.reports-header {
    padding: 22px;
}

.reports-header h1,
.reports-section h2 {
    margin: 0;
    color: var(--text-strong);
    letter-spacing: 0;
}

.reports-header h1 {
    font-size: 1.45rem;
}

.reports-header p {
    margin: 4px 0 0;
    color: var(--text-soft);
    font-size: 0.82rem;
    font-weight: 700;
}

.reports-filters {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 12px;
    padding: 16px;
    align-items: end;
}

.reports-filters > header {
    grid-column: 1 / -1;
}

.reports-filters > header h2 {
    margin: 0;
    color: var(--text-strong);
    font-size: 1rem;
    letter-spacing: 0;
}

.reports-filters .reference-period {
    min-width: 0;
}

.reports-filters .reference-period:has(.reference-calendar-picker) {
    grid-column: auto;
}

.reports-filter-spacer {
    min-height: 64px;
    visibility: hidden;
}

.reports-house-selector {
    display: grid;
    gap: 12px;
    padding: 16px;
}

.reports-house-selector > header {
    display: block;
}

.reports-house-selector > header h2 {
    margin: 0;
    color: var(--text-strong);
    font-size: 1rem;
    letter-spacing: 0;
}

.reports-house-selector > header span {
    min-width: 0;
    overflow: hidden;
    color: var(--text-soft);
    font-size: 0.78rem;
    font-weight: 800;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.reports-house-track {
    display: grid;
    grid-auto-flow: column;
    grid-auto-columns: minmax(210px, 24%);
    grid-template-columns: none;
    gap: 12px;
    max-width: 100%;
    overflow-x: auto;
    overflow-y: hidden;
    overscroll-behavior-x: contain;
    padding: 0 34px 10px 0;
    scroll-snap-type: x proximity;
    scrollbar-gutter: stable;
}

.reports-house-track::-webkit-scrollbar {
    height: 7px;
}

.reports-house-track::-webkit-scrollbar-track {
    border-radius: 999px;
    background: rgba(139, 161, 196, 0.18);
}

.reports-house-track::-webkit-scrollbar-thumb {
    border-radius: 999px;
    background: rgba(139, 161, 196, 0.58);
}

.reports-house-track::-webkit-scrollbar-thumb:hover {
    background: rgba(173, 196, 230, 0.76);
}

.reports-house-card {
    min-height: 82px;
    display: grid;
    place-items: center;
    border: 1px solid var(--border-soft);
    border-radius: 10px;
    padding: 12px 14px;
    background: var(--bg-card-soft);
    color: var(--text-main);
    font: inherit;
    text-align: center;
    cursor: pointer;
    scroll-snap-align: start;
    transition: border-color 0.18s ease, background 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
}

.reports-house-card:hover {
    border-color: rgba(53, 211, 139, 0.32);
}

.reports-house-card.active {
    border-color: var(--brand-red-soft);
    background:
        radial-gradient(circle at 0% 0%, rgba(225, 29, 46, 0.13), transparent 45%),
        var(--bg-card-soft);
    box-shadow: 0 12px 26px rgba(225, 29, 46, 0.08);
}

.reports-house-card strong {
    min-width: 0;
    overflow: hidden;
    color: var(--text-strong);
    font-size: 1.08rem;
    font-weight: 900;
    line-height: 1.16;
    text-overflow: ellipsis;
    white-space: normal;
}

.reports-house-card span {
    color: var(--text-soft);
    font-size: 0.74rem;
    font-weight: 800;
}

.reports-house-card.empty {
    pointer-events: none;
    visibility: hidden;
}

.reports-section-context {
    color: var(--text-soft);
    font-size: 0.78rem;
    font-weight: 800;
}

.reports-period-controls {
    display: grid;
    grid-template-columns: repeat(2, 154px);
    align-items: end;
    gap: 9px;
    transform: translateY(-5px);
}

.reports-period-controls .reference-period {
    min-width: 0;
    width: 154px;
}

.reports-period-controls .reference-period span {
    margin-bottom: 3px;
    font-size: 0.68rem;
}

.reports-period-controls .reference-period select,
.reports-period-controls .reference-selector-surface {
    width: 154px;
    min-height: 34px;
    height: 34px;
    padding-block: 6px;
    font-size: 0.76rem;
}

.reports-period-controls .reference-selector-value {
    font-size: 0.76rem;
}

.reports-period-controls .reference-calendar-icon {
    width: 20px;
    height: 20px;
}

.reports-section {
    display: grid;
    gap: 14px;
    padding: 18px;
}

.reports-section[aria-labelledby="reports-overview-title"] {
    padding-top: 12px;
}

.reports-section[aria-labelledby="reports-page-title"] {
    padding-top: 16px;
}

.reports-page-heading {
    align-items: flex-start !important;
    flex-direction: column;
    justify-content: flex-start !important;
    gap: 8px !important;
}

.reports-page-heading .reports-section-context {
    margin: 5px 0 0;
}

.reports-tabs {
    display: inline-flex;
    align-items: center;
    width: max-content;
    max-width: 100%;
    gap: 6px;
    padding: 5px;
    border: 1px solid var(--border-soft);
    border-radius: 12px;
    background: var(--bg-panel);
}

.reports-tabs button {
    min-height: 34px;
    border: 0;
    border-radius: 9px;
    padding: 0 13px;
    background: transparent;
    color: var(--text-soft);
    cursor: pointer;
    font: inherit;
    font-size: 0.78rem;
    font-weight: 850;
    white-space: nowrap;
    transition: background 0.18s ease, color 0.18s ease, box-shadow 0.18s ease;
}

.reports-tabs button.active {
    background: linear-gradient(180deg, #f43f5e, #d91f2e);
    color: #ffffff;
    box-shadow: 0 10px 20px rgba(225, 29, 46, 0.16);
}

.reports-section > header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
}

.reports-header-tools {
    display: flex;
    align-items: flex-start;
    justify-content: flex-end;
    gap: 10px;
    min-width: 0;
}

.reports-section[aria-labelledby="reports-page-title"] .reports-header-tools {
    justify-content: flex-start;
}

.reports-export-actions {
    display: flex;
    align-items: end;
    min-height: 51px;
}

.reports-export-menu-wrap {
    position: relative;
    width: max-content;
}

.reports-export-button {
    min-height: 34px;
    border: 1px solid rgba(248, 113, 113, 0.34);
    border-radius: 10px;
    padding: 0 13px;
    background: linear-gradient(180deg, #f43f5e, #d91f2e);
    color: #ffffff;
    font: inherit;
    font-size: 0.76rem;
    font-weight: 900;
    white-space: nowrap;
    cursor: pointer;
    box-shadow:
        0 10px 20px rgba(225, 29, 46, 0.16),
        inset 0 1px 0 rgba(255, 255, 255, 0.18);
    transition: transform 0.18s ease, box-shadow 0.18s ease, opacity 0.18s ease;
}

.reports-export-button:hover:not(:disabled) {
    transform: translateY(-1px);
    box-shadow:
        0 13px 24px rgba(225, 29, 46, 0.22),
        inset 0 1px 0 rgba(255, 255, 255, 0.2);
}

.reports-export-button:disabled {
    cursor: not-allowed;
    opacity: 0.72;
}

.reports-export-menu {
    position: absolute;
    top: calc(100% + 7px);
    right: 0;
    z-index: 300010;
    width: 156px;
    display: grid;
    gap: 5px;
    padding: 7px;
    border: 1px solid rgba(139, 161, 196, 0.18);
    border-radius: 11px;
    background: #081626;
    box-shadow:
        0 18px 36px rgba(0, 0, 0, 0.3),
        inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.reports-export-menu button {
    min-height: 31px;
    border: 1px solid rgba(139, 161, 196, 0.14);
    border-radius: 8px;
    padding: 0 10px;
    background: rgba(255, 255, 255, 0.045);
    color: #dce7f5;
    cursor: pointer;
    font-size: 0.71rem;
    font-weight: 800;
    line-height: 1;
    text-align: left;
    transition: border-color 0.18s ease, background 0.18s ease, color 0.18s ease;
}

.reports-export-menu button:hover:not(:disabled) {
    border-color: rgba(248, 113, 113, 0.28);
    background: rgba(225, 29, 46, 0.12);
    color: #ffffff;
}

.reports-export-menu button:disabled {
    cursor: not-allowed;
    opacity: 0.72;
}

.reports-section h2 {
    font-size: 1rem;
}

.reports-metric-group {
    display: grid;
    gap: 6px;
}

.reports-metric-group + .reports-metric-group {
    padding-top: 0;
}

.reports-metric-group h3 {
    margin: 0;
    color: var(--text-soft);
    font-size: 0.84rem;
    font-weight: 900;
}

.reports-metric-group .reference-kpi-row {
    margin-top: 0;
    grid-template-columns: repeat(5, minmax(0, 1fr)) !important;
}

.reports-advanced-section > header {
    display: grid;
    gap: 3px;
}

.reports-advanced-section > header p {
    margin: 5px 0 0;
}

.reports-advanced-section > header h3 {
    margin: 0;
    color: var(--text-strong);
    font-size: 0.94rem;
}

.reports-advanced-layout {
    display: grid;
    gap: 14px;
}

.reports-advanced-group {
    display: grid;
    gap: 8px;
}

.reports-advanced-group h3 {
    margin: 0;
    color: var(--text-soft);
    font-size: 0.84rem;
    font-weight: 900;
}

.reports-advanced-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 10px;
}

.reports-advanced-card {
    min-height: 98px;
    display: grid;
    align-content: center;
    gap: 6px;
    border: 1px solid rgba(139, 161, 196, 0.16);
    border-radius: 12px;
    padding: 14px;
    background: var(--bg-card-soft);
}

.reports-advanced-card span {
    color: var(--text-soft);
    font-size: 0.72rem;
    font-weight: 850;
    line-height: 1.16;
}

.reports-advanced-card strong {
    color: var(--text-strong);
    font-size: 1.12rem;
    font-weight: 950;
    line-height: 1.08;
}

.reports-advanced-card em {
    color: var(--text-soft);
    font-style: normal;
    font-size: 0.72rem;
    font-weight: 800;
}

.reports-advanced-card.positive strong {
    color: var(--profit-green);
}

.reports-advanced-card.negative strong {
    color: var(--loss-red);
}

.reports-grid {
    display: grid;
    grid-template-columns: minmax(0, 1.15fr) minmax(0, 0.85fr);
    gap: 18px;
}

.reports-house-performance {
    border-color: rgba(53, 211, 139, 0.24);
    background:
        radial-gradient(circle at 0% 0%, rgba(53, 211, 139, 0.08), transparent 38%),
        var(--bg-panel);
}

.reports-feature-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 12px;
}

.reports-feature-card {
    min-height: 136px;
    display: grid;
    align-content: center;
    gap: 8px;
    border: 1px solid var(--border-soft);
    border-radius: 14px;
    padding: 18px;
    background: var(--bg-card-soft);
}

.reports-feature-card span,
.reports-placeholder-card em,
.reports-distribution-card span {
    color: var(--text-soft);
    font-size: 0.76rem;
    font-style: normal;
    font-weight: 800;
}

.reports-feature-card strong {
    color: var(--text-strong);
    font-size: 1.28rem;
    line-height: 1.12;
}

.reports-feature-card em {
    font-style: normal;
    font-size: 0.92rem;
    font-weight: 900;
}

.reports-feature-card.positive em {
    color: var(--profit-green);
}

.reports-feature-card.negative em {
    color: var(--loss-red);
}

.reports-feature-card.neutral em {
    color: var(--text-soft);
}

.reports-ranking {
    display: grid;
    gap: 8px;
}

.reports-ranking p {
    margin: 0;
    color: var(--text-soft);
    font-size: 0.84rem;
    font-weight: 750;
}

.reports-ranking div {
    min-height: 46px;
    display: grid;
    grid-template-columns: 34px minmax(0, 1fr) auto;
    align-items: center;
    gap: 10px;
    border: 1px solid var(--border-soft);
    border-radius: 12px;
    padding: 0 12px;
    background: var(--bg-card-soft);
}

.reports-ranking span {
    width: 24px;
    height: 24px;
    display: inline-grid;
    place-items: center;
    border-radius: 999px;
    background: rgba(100, 116, 139, 0.16);
    color: var(--text-soft);
    font-size: 0.72rem;
    font-weight: 900;
}

.reports-ranking strong {
    min-width: 0;
    overflow: hidden;
    color: var(--text-strong);
    font-size: 0.88rem;
    font-weight: 900;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.reports-ranking em {
    color: var(--text-soft);
    font-style: normal;
    font-size: 0.82rem;
    font-weight: 900;
}

.reports-placeholder-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
}

.reports-placeholder-grid.compact {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}

.reports-placeholder-card {
    min-height: 92px;
    display: grid;
    align-content: center;
    gap: 8px;
    border: 1px dashed var(--border);
    border-radius: 12px;
    padding: 14px;
    background: var(--bg-card-soft);
}

.reports-placeholder-card span {
    color: var(--text-soft);
    font-size: 0.78rem;
    font-weight: 800;
}

.reports-placeholder-card strong {
    color: var(--text-strong);
    font-size: 1.25rem;
}

.reports-placeholder-card em {
    font-size: 0.74rem;
}

.reports-distribution-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
}

.reports-distribution-card {
    min-height: 98px;
    display: grid;
    align-content: center;
    gap: 8px;
    border: 1px solid var(--border-soft);
    border-radius: 12px;
    padding: 16px;
    background: var(--bg-card-soft);
}

.reports-distribution-card strong {
    color: var(--text-strong);
    font-size: 1.55rem;
    line-height: 1;
}

.reports-distribution-card.ganhas {
    border-color: var(--profit-green-border);
    background: var(--profit-green-soft);
}

.reports-distribution-card.perdidas {
    border-color: var(--loss-red-border);
    background: var(--loss-red-soft);
}

.auth-switch {
    margin: 12px 0 0;
    color: var(--landing-muted);
    font-size: 0.86rem;
    text-align: center;
}

.auth-switch a {
    color: var(--landing-accent);
    font-weight: 800;
    text-decoration: none;
}

.auth-switch a:hover {
    text-decoration: underline;
}

/* ===== LEGAL PAGES ===== */

.legal-page {
    min-height: 100vh;
}

.legal-main {
    width: min(900px, calc(100% - 44px));
    min-height: 100vh;
    display: grid;
    place-items: center;
    margin: 0 auto;
    padding: 28px 0;
}

.legal-card {
    width: 100%;
    display: grid;
    gap: 18px;
    border: 1px solid var(--landing-border);
    border-radius: 28px;
    padding: 30px;
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.94));
    color: var(--landing-text);
    box-shadow:
        0 28px 72px rgba(15, 23, 42, 0.12),
        0 1px 0 rgba(255, 255, 255, 0.82) inset;
