.legal-header {
    display: grid;
    gap: 8px;
    padding-bottom: 4px;
}

.legal-header span {
    width: fit-content;
    border: 1px solid rgba(225, 29, 46, 0.18);
    border-radius: 999px;
    padding: 5px 10px;
    background: rgba(225, 29, 46, 0.07);
    color: var(--landing-accent);
    font-size: 0.72rem;
    font-weight: 900;
    text-transform: uppercase;
