    font-size: clamp(1.8rem, 3vw, 2.4rem);
    line-height: 1.08;
}

.legal-header p,
.legal-section p {
    margin: 0;
    color: var(--landing-muted);
    font-size: 0.94rem;
    font-weight: 600;
    line-height: 1.62;
}

.legal-section {
    display: grid;
    gap: 7px;
    border-top: 1px solid var(--landing-border);
    padding-top: 16px;
}

.legal-section h2 {
    margin: 0;
    color: var(--landing-text);
    font-size: 1rem;
    line-height: 1.25;
}

.legal-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    border-top: 1px solid var(--landing-border);
