.legal-actions a {
    min-height: 38px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: 1px solid var(--landing-border-strong);
    border-radius: 999px;
    padding: 0 16px;
    background: var(--landing-surface-strong);
    color: var(--landing-text);
    font-size: 0.82rem;
    font-weight: 900;
    text-decoration: none;
    transition: transform 0.18s ease, border-color 0.18s ease, background 0.18s ease;
}

.legal-actions a:first-child {
    border-color: rgba(225, 29, 46, 0.34);
    background: linear-gradient(135deg, var(--landing-accent) 0%, var(--landing-accent-dark) 100%);
    color: #ffffff;
}

.legal-actions a:hover {
    transform: translateY(-1px);
    border-color: rgba(225, 29, 46, 0.36);
}

.landing-hero {
    width: 100%;
    display: grid;
    gap: 16px;
    padding: 0 0 8px;
}

.landing-intro {
    max-width: 1040px;
    margin: 0 auto;
    text-align: center;
}

.landing-intro h1 {
    margin: 0 0 6px;
    color: var(--landing-text);
    font-size: 2.2rem;
    line-height: 1.08;
    font-weight: 800;
    white-space: nowrap;
}

.landing-intro p {
    max-width: 860px;
    margin: 0 auto;
    color: var(--landing-muted);
    font-size: 0.96rem;
    line-height: 1.48;
    font-weight: 500;
    white-space: nowrap;
}

.landing-content {
    display: grid;
    grid-template-columns: minmax(0, 1.06fr) minmax(326px, 0.72fr);
    align-items: stretch;
    gap: 16px;
}

.landing-features {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px 12px;
}

.landing-features article {
    min-height: 104px;
    display: block;
    border: 1px solid var(--landing-border);
    border-radius: 14px;
    padding: 15px 16px;
    background: var(--landing-surface);
    box-shadow: var(--landing-shadow-soft);
    transition: transform 0.22s ease, border-color 0.22s ease, box-shadow 0.22s ease, background 0.22s ease;
}

.landing-features article:hover {
    transform: translateY(-4px);
    border-color: rgba(225, 29, 46, 0.18);
    background: var(--landing-surface-strong);
    box-shadow: var(--landing-shadow-hover);
}

.landing-features article::before {
    content: "";
    display: block;
    width: 7px;
    height: 7px;
    margin-bottom: 12px;
    border-radius: 999px;
    background: var(--landing-accent);
    box-shadow: 0 0 0 4px rgba(225, 29, 46, 0.08);
}

.landing-features strong {
    display: block;
    color: var(--landing-text);
    font-size: 0.95rem;
    line-height: 1.25;
}

.landing-features p {
    margin: 6px 0 0;
    color: var(--landing-muted);
    font-size: 0.8rem;
    line-height: 1.48;
}

.landing-dashboard-preview {
    border: 1px solid var(--landing-border-strong);
    border-radius: 18px;
    padding: 12px;
    background: var(--landing-preview-surface);
    box-shadow: var(--landing-preview-shadow);
    scroll-margin-top: 24px;
    transition: transform 0.22s ease, border-color 0.22s ease, box-shadow 0.22s ease, background 0.22s ease;
}

.landing-dashboard-preview:hover {
    transform: translateY(-4px);
    border-color: rgba(225, 29, 46, 0.22);
    background: var(--landing-preview-surface-hover);
    box-shadow: var(--landing-preview-shadow-hover);
}

.landing-dashboard-preview:target {
    border-color: rgba(225, 29, 46, 0.28);
    box-shadow: 0 24px 54px rgba(185, 28, 28, 0.12);
}

.landing-preview-header span {
    color: var(--landing-accent-dark);
    font-size: 0.74rem;
    font-weight: 800;
    text-transform: uppercase;
}

.landing-preview-header strong {
    display: block;
    margin-top: 0;
    color: var(--landing-text);
    font-size: 1.18rem;
    line-height: 1.2;
}

.landing-preview-metrics {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 9px;
    margin-top: 11px;
}

.landing-preview-metrics div {
    min-height: 68px;
    border: 1px solid var(--landing-border);
    border-radius: 12px;
    padding: 9px;
    background: var(--landing-surface-soft);
}

.landing-preview-metrics span {
    display: block;
    color: var(--landing-muted);
    font-size: 0.76rem;
    font-weight: 700;
}

.landing-preview-metrics strong {
    display: block;
    margin-top: 6px;
    color: var(--landing-text);
    font-size: 1.05rem;
    line-height: 1.15;
}

.landing-preview-metrics strong.landing-preview-positive {
    color: var(--landing-positive);
}

.landing-preview-chart {
    position: relative;
    height: 160px;
    margin-top: 11px;
    padding: 6px 4px 6px 2px;
    border: 1px solid var(--landing-border);
    border-radius: 14px;
    background: var(--landing-chart-surface);
    overflow: hidden;
}

.landing-preview-graph {
    width: 100%;
    height: 100%;
    display: block;
    border-radius: 12px;
    background: var(--landing-chart-inner);
}

.landing-preview-graph-grid line {
    stroke: var(--landing-grid);
    stroke-width: 1;
}

.landing-preview-graph-axis-y text,
.landing-preview-graph-axis-x text {
    fill: var(--landing-axis);
    font-size: 11px;
    font-weight: 700;
}

.landing-preview-graph-axis-x text {
    text-anchor: middle;
}

.landing-preview-graph-area {
    fill: url(#landingPreviewAreaGradient);
}

.landing-preview-graph-line {
    fill: none;
    stroke: color-mix(in srgb, var(--landing-accent) 84%, transparent);
    stroke-width: 5.4;
    stroke-linecap: round;
    stroke-linejoin: round;
    filter: drop-shadow(0 7px 12px rgba(185, 28, 28, 0.12));
}

.landing-preview-graph-points circle {
    fill: var(--landing-surface-strong);
    stroke: color-mix(in srgb, var(--landing-accent) 70%, transparent);
    stroke-width: 3;
}

.landing-preview-graph-points .landing-preview-graph-last-point {
    fill: var(--landing-accent);
    stroke: #ffffff;
    stroke-width: 4;
    filter: drop-shadow(0 8px 16px rgba(185, 28, 28, 0.28));
}

/* ===== HEADER ===== */

.header-left {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 8px;
}

.brand-block {
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 0 0 auto;
}

.logo {
    height: 120px;
    width: auto;
    display: block;
    margin: -40px 8px auto;
}

.title-group {
    margin: 0;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: flex-start;
    gap: 0;
}

.product-name {
    margin: 0;
    font-weight: 800;
    color: #111;
    line-height: 1;
    letter-spacing: 0.3px;
}

.brand-subtitle {
    margin: 0;
    color: var(--text-soft);
    font-weight: 700;
    font-size: 1rem;
    line-height: 1.15;
    letter-spacing: 0.1px;
}

.bet {
    color: #ff000f;
    font-weight: 900;
}

/* ===== ESTRUTURA DO TOPO ===== */

.top-info-row {
    display: flex;
    gap: 16px;
    flex-wrap: wrap;
    align-items: end;
    margin-bottom: 18px;
}

.top-house-form {
    flex: 1 1 420px;
}

.inline-form {
    display: flex;
    gap: 12px;
    flex-wrap: wrap;
    align-items: end;
}

.compact-field {
    flex: 1 1 180px;

}

.compact-button {
    white-space: nowrap;
}

.period-filter-row {
    display: flex;
    gap: 12px;
    flex-wrap: wrap;
    align-items: end;
    flex: 1 1 420px;
}

.period-field {
    width: 120px;
    min-width: 140px;
    flex: 0 0 120px;
}

.top-filter-group .period-field select,
.top-filter-group .date-search-field input {
    height: 42px;
    padding: 6px 10px;
    font-size: 0.93rem;
    border-radius: 10px;
    border-color: rgba(128, 152, 186, 0.34);
    background: linear-gradient(180deg, rgba(18, 31, 50, 0.96) 0%, rgba(13, 24, 40, 0.98) 100%);
    color: #e6edf7;
    box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.055),
        0 8px 18px rgba(0, 0, 0, 0.12);
}

.top-filter-group .period-field select:focus,
.top-filter-group .date-search-field input:focus {
    border-color: rgba(248, 113, 113, 0.82);
    box-shadow:
        0 0 0 3px rgba(225, 29, 46, 0.18),
        0 10px 24px rgba(0, 0, 0, 0.18),
        inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.stats-house-field {
    width: 185px;
    min-width: 185px;
}

.stats-house-field select {
    height: 42px;
    border-color: rgba(128, 152, 186, 0.34);
    background: linear-gradient(180deg, rgba(18, 31, 50, 0.96) 0%, rgba(13, 24, 40, 0.98) 100%);
    color: #e6edf7;
    box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.055),
        0 8px 18px rgba(0, 0, 0, 0.12);
}

.stats-house-field select:focus {
    border-color: rgba(248, 113, 113, 0.82);
    box-shadow:
        0 0 0 3px rgba(225, 29, 46, 0.18),
        0 10px 24px rgba(0, 0, 0, 0.18),
        inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.period-badge {
    background: linear-gradient(180deg, rgba(21, 35, 55, 0.95) 0%, rgba(14, 26, 43, 0.98) 100%);
    border: 1px solid rgba(128, 152, 186, 0.3);
    border-radius: 14px;
    padding: 8px 10px;
    /* menor altura */
    min-width: 170px;
    /* menor largura */
    box-shadow:
        0 12px 26px rgba(0, 0, 0, 0.18),
        inset 0 1px 0 rgba(255, 255, 255, 0.045);
}

.period-badge span {
    display: block;
    font-size: 12px;
    color: var(--text-muted);
    margin-bottom: 6px;
    font-weight: 600;
}

.period-badge strong {
    font-size: 1.05rem;
    color: var(--text-strong);
}

.summary-carousel-section {
    margin-bottom: 16px;
}

.summary-carousel-shell {
    position: relative;
    display: grid;
    grid-template-columns: minmax(0, 1fr) 40px;
    gap: 12px;
    align-items: center;
}

.summary-carousel-viewport {
    overflow: hidden;
    min-width: 0;
}

.summary-carousel-track {
    display: flex;
    transition: transform 0.22s ease;
    will-change: transform;
}

.summary-page {
    flex: 0 0 100%;
    min-width: 0;
}

.summary-four-row {
    display: grid;
    grid-template-columns: repeat(4, minmax(160px, 1fr));
    gap: 12px;
    min-width: 0;
}

.summary-card {
    background: linear-gradient(180deg, rgba(21, 35, 55, 0.95) 0%, rgba(14, 26, 43, 0.98) 100%);
    border: 1px solid rgba(128, 152, 186, 0.3);
    border-radius: 18px;
    padding: 14px 15px;
    min-height: 9px;
    box-shadow:
        0 16px 34px rgba(0, 0, 0, 0.22),
        inset 0 1px 0 rgba(255, 255, 255, 0.045);
    transition:
        border-color 0.2s ease,
        transform 0.2s ease,
        background 0.2s ease,
        box-shadow 0.2s ease;
}

.summary-card:hover {
    transform: translateY(-2px);
    border-color: rgba(148, 173, 211, 0.48);
    box-shadow:
        0 20px 42px rgba(0, 0, 0, 0.28),
        inset 0 1px 0 rgba(255, 255, 255, 0.055);
}

.summary-card.highlight {
    border-color: rgba(148, 173, 211, 0.5);
    box-shadow:
        0 20px 42px rgba(0, 0, 0, 0.28),
        inset 0 1px 0 rgba(255, 255, 255, 0.055);
    background: linear-gradient(180deg, rgba(24, 40, 63, 0.98) 0%, rgba(17, 30, 49, 0.98) 100%);
}

.summary-card:has(.metric-value.positive) {
    background: linear-gradient(180deg, rgba(24, 52, 43, 0.96) 0%, rgba(14, 37, 32, 0.98) 100%);
    border-color: var(--profit-green-border);
    box-shadow:
        0 0 0 1px rgba(74, 222, 128, 0.06) inset,
        0 18px 38px rgba(22, 163, 74, 0.12);
}

.summary-card:has(.metric-value.negative) {
    background: linear-gradient(180deg, rgba(57, 30, 45, 0.96) 0%, rgba(39, 22, 35, 0.98) 100%);
    border-color: var(--loss-red-border);
    box-shadow:
        0 0 0 1px rgba(251, 113, 133, 0.06) inset,
        0 18px 38px rgba(225, 29, 46, 0.12);
}

.summary-card span {
    display: block;
    font-size: 12.5px;
    color: #9fb0c8;
    margin-bottom: 9px;
    font-weight: 800;
    letter-spacing: 0.02em;
}

.summary-card strong {
    color: #f7fbff;
    font-size: 1.24rem;
    line-height: 1.15;
    font-weight: 800;
    letter-spacing: -0.02em;
}

.summary-nav-buttons {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    gap: 8px;
    height: 100%;
}

.summary-outside-nav {
    width: 40px;
    height: 40px;
    min-width: 40px;
    padding: 0;
    display: flex;
    align-items: center;
    justify-content: center;
}

.house-strip {
    position: relative;
    display: grid;
    grid-template-columns: 1fr 4.35fr;
    gap: 12px;
    align-items: stretch;
}

.house-general-card {
    width: 100%;
    min-width: 0;
}

.houses-scroll-area {
    transition: transform 0.22s ease, opacity 0.22s ease;
}

.houses-scroll-area.is-sliding.slide-next {
    opacity: 1;
    transform: translateX(8px);
}

.houses-scroll-area.is-sliding.slide-prev {
    opacity: 1;
    transform: translateX(-8px);
}

.house-card-wrapper {
    position: relative;
    min-width: 0;
}

.house-card {
    width: 100%;
    min-height: 110px;
    text-align: left;
    background:
        radial-gradient(circle at 0% 0%, rgba(148, 173, 211, 0.12), transparent 36%),
        linear-gradient(180deg, rgba(22, 37, 59, 0.96) 0%, rgba(13, 25, 43, 0.98) 100%);
    border: 1px solid rgba(148, 173, 211, 0.28);
    border-radius: 18px;
    padding: 12px;
    color: var(--text-main);
    cursor: default;
    box-shadow:
        0 14px 30px rgba(0, 0, 0, 0.2),
        inset 0 1px 0 rgba(255, 255, 255, 0.045);
    display: flex;
    flex-direction: column;
    justify-content: space-between;
}

.house-card:hover {
    border-color: rgba(173, 196, 230, 0.48);
    transform: none;
    background:
        radial-gradient(circle at 0% 0%, rgba(148, 173, 211, 0.16), transparent 36%),
        linear-gradient(180deg, rgba(24, 39, 61, 0.96) 0%, rgba(17, 30, 49, 0.98) 100%);
}

.house-general-card,
.house-compact-card,
.house-card {
    display: flex;
    flex-direction: column;
    justify-content: space-between;
}

.selected-house-card {
    border-color: var(--brand-red) !important;
    background:
        radial-gradient(circle at 0% 0%, rgba(248, 113, 113, 0.18), transparent 38%),
        linear-gradient(180deg, rgba(37, 25, 39, 0.98) 0%, rgba(22, 24, 39, 0.98) 100%);
    box-shadow:
        0 0 0 1px rgba(225, 29, 46, 0.24) inset,
        0 16px 34px rgba(225, 29, 46, 0.16);
}

.house-card-title {
    font-weight: 800;
    margin-bottom: 8px;
    padding-right: 22px;
    line-height: 1.15;
    font-size: 1.08rem;
    word-break: break-word;
    color: var(--text-strong);
}

.house-small-info {
    display: flex;
    justify-content: space-between;
    gap: 20px;
    /* 🔥 espaço real entre os dois blocos */
    margin-top: 10px;
}

.house-small-info span {
    color: var(--text-soft);
    font-size: 12px;
    font-weight: 500;
    margin-bottom: 2px;
    /* espaço entre label e valor */
}

.house-small-info strong {
    font-size: 13px;
    color: var(--text-strong);
    font-weight: 700;
    margin-top: 2px;
}

.house-menu-area {
    position: absolute;
    top: 6px;
    right: 6px;
}

.menu-dots-button {
    margin: 0;
    width: 14px;
    height: 4px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 6px;
    background: transparent;
    border: none;

    cursor: pointer;
}

.menu-dots-button:hover {
    color: #111111;
}

.house-menu {
    position: absolute;
    top: 24px;
    right: 0;
    min-width: 120px;
    background: #ffffff;
    border: 1px solid var(--border);
    border-radius: 10px;
    overflow: hidden;
    z-index: 20;
    box-shadow: 0 8px 20px rgba(15, 23, 42, 0.12);
}

.house-menu-item {
    width: 100%;
    text-align: left;
    background: transparent;
    border: none;
    color: var(--text-main);
    padding: 10px 12px;
    cursor: pointer;
    font-family: "Poppins", Arial, Helvetica, sans-serif;
}

.house-menu-item:hover {
    background: #f8fafc;
}

.house-menu-item.danger-item {
    color: #dc2626;
}

.houses-nav-buttons {
    position: absolute;
    right: 8px;
    top: 50%;
    transform: translateY(-50%);
    display: flex;
    flex-direction: column;
    gap: 8px;
    z-index: 20;
}

.nav-mini-button {
    width: 40px;
    height: 40px;
    min-width: 40px;
    padding: 0;
    display: flex;
    align-items: center;
    justify-content: center;
}


/* ===== TIPOGRAFIA E FORMULÁRIOS ===== */

h2 {
    margin: 0 0 14px 0;
    color: var(--text-strong);
    font-weight: 800;
    font-size: 1.15rem;
}

.form-stack {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
}

.field-group {
    display: flex;
    flex-direction: column;
}

.field-group label {
    font-size: 13px;
    color: #b8c4d6;
    font-weight: 600;
    margin-bottom: 4px;
}

input,
select,
textarea {
    width: 100%;
    padding: 10px 12px;
    padding-right: 10.5px;
    border-radius: 13px;
    border: 1px solid rgba(128, 152, 186, 0.3);
    background: linear-gradient(180deg, rgba(18, 31, 50, 0.96) 0%, rgba(13, 24, 40, 0.98) 100%);
    color: var(--text-main);
    outline: none;
    font-family: "Poppins", Arial, Helvetica, sans-serif;
    font-size: 0.98rem;
    transition:
        border-color 0.2s ease,
        box-shadow 0.2s ease,
        background 0.2s ease;
    box-sizing: border-box;
}

input:focus,
select:focus,
textarea:focus {
    border-color: rgba(225, 29, 46, 0.75);
    box-shadow: 0 0 0 3px rgba(225, 29, 46, 0.10);
}

textarea {
    resize: vertical;
}

.button-row {
    display: flex;
    gap: 10px;
}

.primary-button,
.secondary-button,
.danger-button {
    border: none;
    border-radius: 13px;
    padding: 10px 14px;
    cursor: pointer;
    font-weight: 700;
    font-family: "Poppins", Arial, Helvetica, sans-serif;
    transition:
        transform 0.2s ease,
        opacity 0.2s ease,
        background 0.2s ease,
        border-color 0.2s ease,
        box-shadow 0.2s ease;
}

.primary-button:hover,
.secondary-button:hover,
.danger-button:hover {
    transform: translateY(-1px);
}

.primary-button {
    background: linear-gradient(180deg, var(--brand-red) 0%, #d81426 100%);
    color: #ffffff;
    box-shadow: 0 8px 18px rgba(225, 29, 46, 0.18);
}

.primary-button:hover {
    background: linear-gradient(180deg, #d81426 0%, var(--brand-red-dark) 100%);
}

.secondary-button {
    background: linear-gradient(180deg, #f3f7fc 0%, #e7edf6 100%);
    color: #111827;
    border: 1px solid #c9d2de;
}

.secondary-button:hover {
    background: linear-gradient(180deg, #edf3fa 0%, #dfe7f2 100%);
}

.danger-button {
    background: linear-gradient(180deg, #dc2626 0%, #c81e1e 100%);
    color: #ffffff;
}

.danger-button:hover {
    background: linear-gradient(180deg, #c81e1e 0%, #b91c1c 100%);
}

.secondary-button:disabled,
.primary-button:disabled,
.danger-button:disabled {
    opacity: 0.5;
    cursor: not-allowed;
    transform: none;
}

.section-header {
    margin-bottom: 14px;
}

.dashboard-collapse-trigger {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    margin-bottom: 14px;
    padding: 0;
    border: 0;
    background: transparent;
    color: var(--text-strong);
    text-align: left;
    font: inherit;
    cursor: pointer;
}

.dashboard-collapse-title {
    color: var(--text-strong);
    font-size: 1.15rem;
    font-weight: 800;
    line-height: 1.2;
}

.dashboard-collapse-caret {
    width: 28px;
    height: 28px;
    display: inline-grid;
    flex: 0 0 auto;
    place-items: center;
    border: 1px solid rgba(148, 163, 184, 0.32);
    border-radius: 999px;
    background: #ffffff;
    transition: transform 0.18s ease, border-color 0.18s ease, background 0.18s ease;
}

.dashboard-collapse-caret::before {
    content: "";
    width: 7px;
    height: 7px;
    border-right: 2px solid #64748b;
    border-bottom: 2px solid #64748b;
    transform: translateY(-1px) rotate(45deg);
    transition: border-color 0.18s ease;
}

.dashboard-collapse-trigger[aria-expanded="true"] .dashboard-collapse-caret {
    border-color: rgba(225, 29, 46, 0.24);
    background: #fff7f7;
    transform: rotate(180deg);
}

.dashboard-collapse-trigger[aria-expanded="true"] .dashboard-collapse-caret::before {
    border-color: var(--brand-red-dark);
}

.day-nav {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    align-items: end;
    margin-bottom: 16px;
}

.date-search-field {
    min-width: 180px;
    width: 180px;
}

/* ===== LISTAS / CARDS ===== */

.ticket-list,
.movement-list {
    display: flex;
    flex-direction: column;
    gap: 14px;
}

.scrollable-list {
    max-height: 560px;
    overflow-y: auto;
    padding-right: 6px;
}

.scrollable-list::-webkit-scrollbar {
    width: 8px;
}

.scrollable-list::-webkit-scrollbar-track {
    background: #f1f5f9;
    border-radius: 999px;
}

.scrollable-list::-webkit-scrollbar-thumb {
    background: #cbd5e1;
    border-radius: 999px;
}

.scrollable-list::-webkit-scrollbar-thumb:hover {
    background: #94a3b8;
}

.ticket-card,
.movement-card {
    background: linear-gradient(180deg, #f3f7fc 0%, #eaf0f8 100%);
    border: 1px solid var(--border);
    border-radius: 18px;
    padding: 14px;
    box-shadow: var(--shadow-card);
}

.ticket-top,
.movement-top {
    display: flex;
    justify-content: space-between;
    gap: 12px;
    align-items: start;
    margin-bottom: 14px;
    flex-wrap: wrap;
}

.ticket-title,
.movement-title {
    font-weight: 800;
    margin-bottom: 4px;
    color: var(--text-strong);
}

.ticket-subtitle,
.movement-subtitle {
    font-size: 13px;
    color: var(--text-soft);
}

.status-badge {
    border-radius: 999px;
    padding: 8px 14px;
    font-size: 13px;
    font-weight: 800;
    letter-spacing: 0.2px;
    min-width: 96px;
    text-align: center;
    display: inline-flex;
    align-items: center;
    justify-content: center;
}

.status-badge.green {
    background: linear-gradient(180deg, #dcfce7 0%, #bbf7d0 100%);
    color: #166534;
    border: 1px solid #86efac;
    box-shadow: 0 4px 10px rgba(34, 197, 94, 0.18);
}

.status-badge.red {
    background: linear-gradient(180deg, #fee2e2 0%, #fecaca 100%);
    color: #991b1b;
    border: 1px solid #fca5a5;
    box-shadow: 0 4px 10px rgba(239, 68, 68, 0.18);
}

.status-badge.pending {
    background: #f1f5f9;
    color: #334155;
    border: 2px solid #94a3b8;
    /* contorno mais forte */
    box-shadow: 0 2px 6px rgba(148, 163, 184, 0.25);
}

.status-badge.cashout {
    background: linear-gradient(180deg, #fef3c7 0%, #fde68a 100%);
    color: #92400e;
    border: 1px solid #facc15;
    box-shadow: 0 4px 10px rgba(250, 204, 21, 0.22);
}

.ticket-info-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
    gap: 10px;
    margin-bottom: 12px;
}

.info-box {
    background: linear-gradient(180deg, #fbfcfe 0%, #f2f6fb 100%);
    border: 1px solid #d7dee8;
    border-radius: 12px;
    padding: 12px;
}

.info-box span {
    display: block;
    font-size: 12px;
    color: var(--text-soft);
    margin-bottom: 6px;
    font-weight: 500;
}

.info-box strong {
    color: var(--text-strong);
    font-weight: 700;
}

.ticket-note,
.movement-note {
    background: linear-gradient(180deg, #fbfcfe 0%, #f3f6fb 100%);
    border: 1px solid #d7dee8;
    border-radius: 12px;
    padding: 12px;
    font-size: 13px;
    margin-bottom: 12px;
    color: var(--text-main);
}

.movement-positive {
    color: var(--profit-green);
}

.movement-negative {
    color: var(--loss-red);
}

.ticket-actions,
.card-actions {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
    margin-top: 10px;
}

.empty-state {
    background: #f8fafc;
    border: 1px dashed #cbd5e1;
    border-radius: 14px;
    padding: 20px;
    color: var(--text-soft);
    text-align: center;
}

.empty-state strong {
    display: block;
    color: var(--text-strong);
    font-size: 0.92rem;
    font-weight: 800;
}

.empty-state-hint {
    display: block;
    margin-top: 5px;
    color: #64748b;
    font-size: 0.8rem;
    font-weight: 600;
}

hr.section-divider {
    border: none;
    border-top: 1px solid #e5e7eb;
    margin: 4px 0 0;
}

/* ===== COLAPSÁVEIS ===== */

.collapsible-content {
    display: block;
    height: auto;
    overflow: hidden;
    transition: all 0.25s ease;
    opacity: 1;
}

.collapsible-content.closed {
    height: 0;
    opacity: 0;
    overflow: hidden;
    padding: 0 !important;
    margin: 0 !important;
}

.collapsible-inner {
    overflow: hidden;
}

.split-title {
    margin-top: 10px;
    margin-bottom: 4px;
    font-size: 12.5px;
    font-weight: 700;
    color: #6b7280;
}

/* ===== BILHETES DO DIA ===== */

.tickets-day-panel {
    display: flex;
    flex-direction: column;
    min-height: 257px;
}

.tickets-day-panel .day-nav {
    margin-bottom: 10px;
}

.collapsed-ticket-list {
    display: flex;
    flex-direction: column;
    gap: 10px;
    margin-top: 0;
    max-height: 170px;
    overflow-y: auto;
    overflow-x: hidden;
    padding-right: 6px;
    flex-shrink: 0;
}

.collapsed-ticket-list:has(.collapsed-ticket-card.open) {
    max-height: none;
    overflow-y: visible;
    padding-right: 0;
}

.collapsed-ticket-card {
    background: linear-gradient(180deg, #f3f7fc 0%, #e9f0f8 100%);
    border: 1px solid var(--border-soft);
    border-radius: 14px;
    box-shadow: var(--shadow-card);
    overflow: visible;
}

.collapsed-ticket-card.open {
    box-shadow: var(--shadow-card-strong);
    overflow: visible;
}

.collapsed-ticket-item {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 12px;
    text-align: left;
    background: transparent;
    border: none;
    padding: 12px 14px;
    min-height: 64px;
    cursor: pointer;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.collapsed-ticket-item:hover {
    transform: translateY(-1px);
}

.collapsed-ticket-main {
    display: flex;
    flex-direction: column;
    gap: 6px;
    min-width: 0;
}

.collapsed-ticket-name {
    font-size: 15px;
    font-weight: 600;
    color: #0f172a;

    letter-spacing: 0.2px;
    line-height: 1.2;
}

.collapsed-ticket-meta {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    font-size: 0.86rem;
    color: var(--text-soft);
    font-weight: 500;
}

.collapsed-ticket-status {
    display: inline-flex;
    align-items: center;
    justify-content: center;

    padding: 6px 12px;
    border-radius: 999px;

    font-size: 13px;
    font-weight: 800;

    background: #f1f5f9;
    color: #334155;
    border: 2px solid #94a3b8;

    min-width: 90px;
}

.collapsed-ticket-status.green {
    background: #f0fdf4;
    color: #166534;
    border: 2px solid #22c55e;
}

.collapsed-ticket-status.red {
    background: #fef2f2;
    color: #991b1b;
    border: 2px solid #ef4444;
}

.collapsed-ticket-status.pending {
    background: #f1f5f9;
    color: #334155;
    border: 2px solid #94a3b8;
    box-shadow: 0 2px 6px rgba(148, 163, 184, 0.25);
}

.collapsed-ticket-status.cashout {
    background: #fffbeb;
    color: #92400e;
    border: 2px solid #f59e0b;
}

.collapsed-ticket-detail {
    padding: 0 14px 14px 14px;
    margin-top: 0;
    background: transparent;
    border: none;
    box-shadow: none;
}

.collapsed-ticket-card.open .ticket-info-grid,
.collapsed-ticket-card.open .ticket-note,
.collapsed-ticket-card.open .card-actions {
    overflow: visible;
}

.tickets-day-panel .collapsed-ticket-list::-webkit-scrollbar {
    width: 8px;
}

.tickets-day-panel .collapsed-ticket-list::-webkit-scrollbar-track {
    background: #f1f5f9;
    border-radius: 999px;
}

.tickets-day-panel .collapsed-ticket-list::-webkit-scrollbar-thumb {
    background: #cbd5e1;
    border-radius: 999px;
}

.tickets-day-panel .collapsed-ticket-list::-webkit-scrollbar-thumb:hover {
    background: #94a3b8;
}

/* ===== TOPO BILHETES ===== */

.tickets-topbar {
    position: relative;
    display: flex;
    align-items: center;
    min-height: 46px;
    margin-bottom: 6px;
}

.tickets-title-wrap {
    margin-bottom: 0;
    flex: 0 0 auto;
    z-index: 2;
}

.tickets-date-nav {
    position: absolute;
    left: 50%;
    transform: translateX(-50%);
    display: flex;
    align-items: center;
    gap: 6px;
}

.tickets-date-field {
    display: flex;
    align-items: center;
    justify-content: center;
}

.tickets-date-field input {
    width: 120px;
    padding: 6px 8px;
    text-align: center;
    font-size: 0.85rem;
}

.tickets-date-nav .nav-mini-button {
    width: 32px;
    height: 32px;
    min-width: 32px;
    padding: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
}

.day-nav-center {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    margin: 10px 0;
}

.day-nav-center input {
    width: 160px;
    padding: 8px 10px;
    text-align: center;
    border-radius: 10px;
}

.day-nav-center .nav-mini-button {
    width: 40px;
    height: 40px;
    min-width: 40px;
    padding: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 14px;
    background: linear-gradient(180deg, #f3f7fc 0%, #e7edf6 100%);
    border: 1px solid #c9d2de;
    color: #111827;
    cursor: pointer;
    transition: all 0.2s ease;
}

.day-nav-center .nav-mini-button:hover {
    background: linear-gradient(180deg, #edf3fa 0%, #dfe7f2 100%);
    transform: translateY(-1px);
}

/* ===== TOPO DESKTOP REORGANIZADO ===== */

.top-desktop-layout {
    display: flex;
    flex-direction: column;
    gap: 16px;
    overflow: visible;
}

.top-house-form-row {
    display: flex;
    gap: 10px;
    align-items: end;
    padding: 1px 0 0;
}

.top-house-form-inline {
    display: flex;
    align-items: flex-end;
    gap: 12px;
    /* mais espaço entre os campos */
    flex-wrap: nowrap;
    width: auto;
    position: relative;
}

.top-house-field {
    min-width: 0;
    max-width: none;
    flex: 0 0 180px;
}

.top-house-bank-field {
    flex: 0 0 135px;
    width: 135px;
    min-width: 135px;
}

.top-house-field input,
.top-house-bank-field input {
    height: 33px;
    padding: 4px 9px;
    font-size: 0.88rem;
    border-radius: 10px;
    border-color: rgba(128, 152, 186, 0.34);
    background: linear-gradient(180deg, rgba(18, 31, 50, 0.96) 0%, rgba(13, 24, 40, 0.98) 100%);
    color: #e6edf7;
    box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.055),
        0 8px 18px rgba(0, 0, 0, 0.12);
    transition: border-color 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
}

.top-house-field input:focus,
.top-house-bank-field input:focus {
    border-color: rgba(248, 113, 113, 0.82);
    background: rgba(18, 31, 50, 1);
    box-shadow:
        0 0 0 3px rgba(225, 29, 46, 0.18),
        0 10px 24px rgba(0, 0, 0, 0.18),
        inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.top-house-field input:hover,
.top-house-bank-field input:hover {
    border-color: rgba(148, 173, 211, 0.48);
}

.top-house-field label,
.top-house-bank-field label {
    color: #b8c4d6;
    font-size: 12px;
    font-weight: 800;
    margin-bottom: 3px;
}

.top-house-add-button,
.top-house-cancel-button {
    height: 35px;
    padding: 4px 10px;
    font-size: 0.91rem;
    border-radius: 11px;
    white-space: nowrap;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    box-shadow: 0 8px 18px rgba(15, 23, 42, 0.055);
}

.top-house-add-button {
    border-color: rgba(248, 113, 113, 0.36);
    background: linear-gradient(180deg, #f43f5e 0%, #d91f2e 100%);
    color: #ffffff;
    box-shadow:
        0 14px 28px rgba(225, 29, 46, 0.28),
        inset 0 1px 0 rgba(255, 255, 255, 0.2);
}

.top-house-cancel-button {
    min-width: 96px;
    background: rgba(18, 31, 50, 0.88);
    border: 1px solid rgba(128, 152, 186, 0.28);
    color: #c7d3e5;
    transition:
        background 0.2s ease,
        transform 0.15s ease,
        box-shadow 0.2s ease;
}

.top-house-cancel-button:hover {
    background: rgba(25, 42, 65, 0.94);
    transform: translateY(-1px);
}

.top-house-cancel-button:active {
    transform: translateY(0);
}

.top-houses-arrows {
    width: 100%;
    display: flex;
    justify-content: flex-end;
    align-items: center;
    gap: 8px;
    margin-top: -4px;
    margin-bottom: 4px;
    padding-right: 0;
}

.top-house-arrow {
    width: 40px;
    height: 40px;
    min-width: 40px;
    padding: 0;
    display: flex;
    align-items: center;
    justify-content: center;
}

.top-houses-row {
    display: grid;
    grid-template-columns: 1fr;
    gap: 12px;
    width: 100%;
    min-width: 0;
}

.top-houses-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 12px;
    width: 100%;
    touch-action: pan-y;
    user-select: none;
    -webkit-user-select: none;
}

.top-houses-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 12px;
    width: 100%;
    touch-action: pan-y;
    user-select: none;
    -webkit-user-select: none;
    transition: transform 0.22s ease;
}

.top-houses-grid.is-sliding.slide-next {
    transform: translateX(8px);
}

.top-houses-grid.is-sliding.slide-prev {
    transform: translateX(-8px);
}

.top-house-card-wrap {
    min-width: 0;
    position: relative;
    align-self: start;
}

.top-house-card,
.top-house-card-button,
.top-house-card-title,
.top-house-card-info,
.top-house-card-info span,
.top-house-card-info strong {
    font-family: "Poppins", Arial, Helvetica, sans-serif;
}

.top-house-card {
    width: 100%;
    min-height: 148px;
    /* aumenta um pouco a altura */
    text-align: left;
    background:
        radial-gradient(circle at 0% 0%, rgba(148, 173, 211, 0.11), transparent 36%),
        radial-gradient(circle at 100% 0%, rgba(56, 189, 248, 0.045), transparent 30%),
        linear-gradient(180deg, rgba(21, 36, 58, 0.95) 0%, rgba(12, 24, 42, 0.98) 100%);
    border: 1px solid rgba(148, 173, 211, 0.24);
    border-radius: 26px;
    padding: 18px 18px 28px;
    /* mais respiro interno */
    color: var(--text-main);
    box-shadow:
        0 16px 36px rgba(0, 0, 0, 0.22),
        inset 0 1px 0 rgba(255, 255, 255, 0.055);
    display: flex;
    flex-direction: column;
    justify-content: flex-start;
    gap: 16px;
    position: relative;
    overflow: hidden;
    transition:
        transform 0.2s ease,
        border-color 0.2s ease,
        background 0.2s ease,
        box-shadow 0.2s ease;
}

.top-house-card::before {
    content: "";
    position: absolute;
    inset: 0;
    pointer-events: none;
    background:
        linear-gradient(90deg, rgba(255, 255, 255, 0.06), transparent 34%),
        linear-gradient(180deg, rgba(255, 255, 255, 0.04), transparent 50%);
    opacity: 0.6;
}

.top-house-card::after {
    content: "";
    position: absolute;
    left: 18px;
    right: 18px;
    bottom: 14px;
    height: 24px;
    pointer-events: none;
    border-radius: 999px;
    background:
        linear-gradient(135deg,
            transparent 0 16%,
            rgba(148, 173, 211, 0.14) 17% 20%,
            transparent 21% 34%,
            rgba(248, 113, 113, 0.22) 35% 38%,
            transparent 39% 52%,
            rgba(74, 222, 128, 0.22) 53% 56%,
            transparent 57% 72%,
            rgba(56, 189, 248, 0.18) 73% 76%,
            transparent 77% 100%),
        linear-gradient(180deg, transparent 44%, rgba(148, 173, 211, 0.11) 45% 52%, transparent 53%);
    opacity: 0.66;
}

.top-house-card:hover {
    transform: translateY(-1px);
    border-color: rgba(173, 196, 230, 0.42);
    background:
        radial-gradient(circle at 0% 0%, rgba(148, 173, 211, 0.16), transparent 36%),
        linear-gradient(180deg, rgba(26, 43, 67, 0.98) 0%, rgba(15, 29, 49, 0.98) 100%);
    box-shadow:
        0 20px 44px rgba(0, 0, 0, 0.26),
        inset 0 1px 0 rgba(255, 255, 255, 0.055);
}

.top-house-card.selected-house-card {
    border-color: rgba(248, 113, 113, 0.42);
    background:
        radial-gradient(circle at 0% 0%, rgba(248, 113, 113, 0.18), transparent 38%),
        linear-gradient(180deg, rgba(43, 28, 44, 0.98) 0%, rgba(23, 25, 42, 0.98) 100%);
    box-shadow:
        0 0 0 1px rgba(225, 29, 46, 0.22) inset,
        0 18px 40px rgba(225, 29, 46, 0.13);
}

.top-house-card.selected-house-card:hover {
    border-color: var(--brand-red) !important;
    background:
        radial-gradient(circle at 0% 0%, rgba(248, 113, 113, 0.2), transparent 38%),
        linear-gradient(180deg, rgba(43, 28, 44, 0.98) 0%, rgba(23, 25, 42, 0.98) 100%) !important;
    box-shadow:
        0 0 0 1px rgba(225, 29, 46, 0.24) inset,
        0 18px 38px rgba(225, 29, 46, 0.18) !important;
    transform: translateY(-2px) !important;
}

.top-house-general-card {
    min-width: 0;
    align-self: start;
    background:
        radial-gradient(circle at 0% 0%, rgba(56, 189, 248, 0.1), transparent 36%),
        linear-gradient(180deg, rgba(18, 31, 50, 0.98) 0%, rgba(12, 23, 39, 0.98) 100%);
    border-color: rgba(148, 173, 211, 0.38);
    box-shadow: 0 16px 34px rgba(0, 0, 0, 0.22);
}

.top-house-general-card:hover {
    background: linear-gradient(180deg, rgba(21, 36, 58, 0.98) 0%, rgba(14, 26, 43, 0.98) 100%);
}

.top-house-general-card .top-house-card-title {
    font-size: 0.98rem;

}

.top-house-card-button {
    width: 100%;
    border: none;
    background: transparent;
    padding: 0;
    margin: 0;
    text-align: left;
    cursor: pointer;
    display: flex;
    flex-direction: column;
    gap: 6px;
    color: inherit;
    position: relative;
    z-index: 1;
}

.top-house-card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 8px;
    margin-bottom: 7px;
    /* volta pro normal */
}

.top-house-card-title {
    font-size: 1.1rem;
    font-weight: 900;
    color: #f8fbff;
    letter-spacing: -0.2px;
    line-height: 1.15;
}

.top-house-card-info {
    display: grid;
    grid-template-columns: 1fr auto;
    align-items: center;
    gap: 10px;
    width: 100%;
    margin-top: 10px;
}

.top-house-card:not(.top-house-general-card) .top-house-card-info+.top-house-card-info {
    margin-top: 0;
}

.top-house-general-card .top-house-card-info+.top-house-card-info {
    margin-top: -10px;
}

.top-house-card-info span {
    font-size: 0.75rem;
    color: #8799b2;
    font-weight: 700;
}

.top-house-card-info strong {
    font-size: 1.14rem;
    font-weight: 800;
    color: #f7fbff;
    text-shadow: 0 8px 20px rgba(0, 0, 0, 0.22);
    text-align: right;
    letter-spacing: -0.01em;
}

.top-house-menu-box {
    position: absolute;
    top: 8px;
    right: 4px;

    min-width: 92px;

    display: flex;
    flex-direction: column;
    gap: 4px;

    padding: 6px;

    background: rgba(12, 23, 39, 0.98);
    border: 1px solid rgba(128, 152, 186, 0.3);
    border-radius: 10px;

    box-shadow: 0 18px 36px rgba(0, 0, 0, 0.32);

    z-index: 20;
}

.top-house-menu-box .house-menu-item {
    border-radius: 10px;
    border: 1px solid transparent;
    background: rgba(18, 31, 50, 0.96);
    color: #dbe6f5;
    height: 28px;
    padding: 4px 8px;
    font-size: 0.78rem;

}

.top-house-menu-box .house-menu-item:hover {
    background: rgba(30, 48, 74, 0.98);
}

.top-house-empty-state {
    min-height: 110px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.top-filter-summary-row {
    display: grid;
    grid-template-columns: minmax(220px, 1fr) minmax(180px, 240px);
    gap: 12px;
    align-items: end;
}

.top-filter-group {
    display: flex;
    align-items: end;
    gap: 12px;
    flex-wrap: wrap;
    width: 100%;
    min-width: 0;
}

/* ===== ESTATÍSTICAS SUPERIORES ===== */

.stats-top-section {
    display: block;
}

.stats-top-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 18px;
    min-width: 0;
    transition: opacity 0.18s ease, transform 0.18s ease;
}

.stats-top-grid.is-sliding.slide-next {
    opacity: 0;
    transform: translateX(-12px);
}

.stats-top-grid.is-sliding.slide-prev {
    opacity: 0;
    transform: translateX(12px);
}

.stats-top-arrows {
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    align-items: center;
    gap: 8px;
}

.stats-top-arrows-inline {
    display: flex;
