.reference-brand {
    margin: 0 18px 38px;
    color: #f8fbff;
    font-size: 2rem;
    font-weight: 950;
    letter-spacing: -0.07em;
    line-height: 1;
}

.reference-brand strong {
    color: #ff243d;
    font: inherit;
}

.reference-nav {
    display: grid;
    gap: 10px;
}

.reference-nav-item {
    min-height: 59px;
    display: flex;
    align-items: center;
    gap: 19px;
    border: 1px solid transparent;
    border-radius: 13px;
    padding: 0 20px;
    background: transparent;
    color: #94a6bf;
    font-size: 0.95rem;
    font-weight: 800;
    text-align: left;
}

.reference-nav-item.active {
    color: #fff;
    background: linear-gradient(90deg, rgba(255, 36, 61, 0.48), rgba(255, 36, 61, 0.09));
    border-color: rgba(255, 36, 61, 0.22);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06), 0 16px 34px rgba(255, 36, 61, 0.12);
}

.reference-nav-item:disabled {
    cursor: not-allowed;
    opacity: 0.55;
}

.ref-icon,
.reference-kpi-icon,
.reference-action-icon {
    position: relative;
    display: inline-grid;
    place-items: center;
    flex: 0 0 auto;
}

.ref-icon {
    width: 18px;
    height: 18px;
    color: currentColor;
}

.ref-icon::before,
.ref-icon::after,
.reference-kpi-icon::before,
.reference-kpi-icon::after,
.reference-action-icon::before,
.reference-action-icon::after {
    content: "";
    position: absolute;
    color: currentColor;
}

.ref-icon::before {
    inset: 2px;
    border: 1.7px solid currentColor;
    border-radius: 4px;
}

.ref-icon-grid::before {
    box-shadow: 8px 0 0 -3px currentColor, 0 8px 0 -3px currentColor, 8px 8px 0 -3px currentColor;
}

.ref-icon-sync::before,
.ref-icon-gear::before {
    border-radius: 999px;
}

.ref-icon-calendar::before {
    inset: 1px;
    border-radius: 4px;
    box-shadow: inset 0 4px 0 rgba(213, 223, 237, 0.2);
}

.reference-upgrade-card {
    margin: auto 10px 0;
    display: grid;
    justify-items: center;
    gap: 10px;
    border: 1px solid rgba(255, 36, 61, 0.26);
    border-radius: 20px;
    padding: 25px 16px 18px;
    background: linear-gradient(180deg, rgba(18, 32, 54, 0.82), rgba(8, 19, 34, 0.92));
    text-align: center;
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

.reference-crown {
    width: 26px;
    height: 20px;
    border: 1.8px solid #95a6bd;
    border-top: 0;
    clip-path: polygon(0 100%, 0 42%, 22% 60%, 50% 0, 78% 60%, 100% 42%, 100% 100%);
}

.reference-upgrade-card strong {
    font-size: 0.88rem;
}

.reference-upgrade-card b {
    color: #ff2b43;
    font-size: 0.88rem;
}

.reference-upgrade-card p {
    max-width: 178px;
    margin: 0 0 7px;
    color: #96a7bd;
    font-size: 0.79rem;
    line-height: 1.45;
}

.reference-upgrade-card button {
    width: 100%;
    min-height: 42px;
    border: 1px solid rgba(255, 36, 61, 0.54);
    border-radius: 10px;
    background: transparent;
    color: #ff2b43;
    font-size: 0.84rem;
    font-weight: 900;
}

.reference-main {
    min-width: 0;
    padding: 16px 20px 26px 24px;
}

.reference-header {
    min-height: 61px;
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 24px;
    margin-bottom: 13px;
}

.reference-header h1 {
    margin: 7px 0 3px;
    color: #f6f9ff;
    font-size: 1.42rem;
    font-weight: 950;
    line-height: 1.05;
    letter-spacing: -0.03em;
}

.reference-header p {
    margin: 0;
    color: #9aaabe;
    font-size: 0.86rem;
    font-weight: 600;
}

.reference-account-wrap {
    position: relative;
    width: 214px;
}

.reference-account {
    width: 214px;
    min-height: 62px;
    display: grid;
    grid-template-columns: 38px minmax(0, 1fr) 14px;
    grid-template-rows: auto auto;
    align-items: center;
    column-gap: 12px;
    border: 1px solid rgba(139, 161, 196, 0.16);
    border-radius: 12px;
    padding: 8px 12px;
    background: linear-gradient(180deg, rgba(20, 34, 56, 0.92), rgba(13, 25, 43, 0.98));
    color: #fff;
    text-align: left;
}

.reference-account > span {
    grid-row: 1 / 3;
    width: 38px;
    height: 38px;
    display: grid;
    place-items: center;
    border-radius: 999px;
    background: #ff243d;
    font-size: 0.84rem;
    font-weight: 950;
}

.reference-account strong {
    overflow: hidden;
    font-size: 0.82rem;
    font-weight: 900;
    line-height: 1.1;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.reference-account small {
    color: #a8b5c7;
    font-size: 0.72rem;
    font-weight: 700;
}

.reference-account i {
    grid-row: 1 / 3;
    width: 8px;
    height: 8px;
    border-right: 2px solid #a8b5c7;
    border-bottom: 2px solid #a8b5c7;
    transform: rotate(45deg) translateY(-3px);
}

.reference-account-menu {
    position: absolute;
    top: calc(100% + 8px);
    right: 0;
    z-index: 20;
    min-width: 138px;
    border: 1px solid rgba(139, 161, 196, 0.16);
    border-radius: 12px;
    padding: 6px;
    background: #0d192b;
    box-shadow: 0 16px 34px rgba(0, 0, 0, 0.28);
}

.reference-account-menu button {
    width: 100%;
    border: 0;
    border-radius: 9px;
    padding: 10px 12px;
    background: transparent;
    color: #f6f9ff;
    font-size: 0.8rem;
    font-weight: 900;
    text-align: left;
    cursor: pointer;
}

.reference-account-menu button:hover {
    background: rgba(255, 36, 61, 0.12);
    color: #ff9aaa;
}

.reference-account-menu button:disabled {
    cursor: wait;
    opacity: 0.7;
}

.reference-control-panel {
    border: 1px solid rgba(139, 161, 196, 0.14);
    border-radius: 15px;
    padding: 16px;
    background: linear-gradient(180deg, rgba(15, 27, 46, 0.94), rgba(10, 21, 37, 0.97));
    box-shadow: 0 20px 42px rgba(0, 0, 0, 0.22);
}

.reference-loading-panel {
    margin-bottom: 12px;
    border: 1px solid rgba(139, 161, 196, 0.16);
    border-radius: 12px;
    padding: 12px 14px;
    background: rgba(15, 27, 46, 0.72);
    color: #aebdd1;
    font-size: 0.82rem;
    font-weight: 700;
}

.reference-load-error-panel {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    margin-bottom: 12px;
    border: 1px solid rgba(255, 36, 61, 0.28);
    border-radius: 12px;
    padding: 12px 14px;
    background: rgba(255, 36, 61, 0.1);
    color: #ff9aaa;
    font-size: 0.82rem;
    font-weight: 700;
}

.reference-load-error-panel button {
    border: 1px solid rgba(255, 154, 170, 0.34);
    border-radius: 7px;
    padding: 7px 10px;
    background: rgba(8, 18, 32, 0.42);
    color: #fff;
    font-size: 0.78rem;
    font-weight: 850;
}

.reference-toolbar {
    display: grid;
    grid-template-columns: 238px 230px 140px minmax(0, 1fr) 224px 218px;
    align-items: end;
    gap: 16px;
    padding: 4px 12px 16px;
    border-bottom: 1px solid rgba(139, 161, 196, 0.08);
}

.reference-toolbar label {
    display: grid;
    gap: 5px;
}

.reference-toolbar label span {
    color: #a7b5c8;
    font-size: 0.75rem;
    font-weight: 800;
}

.reference-toolbar input,
.reference-toolbar select,
.reference-month {
    width: 100%;
    height: 40px;
    border: 1px solid rgba(139, 161, 196, 0.28);
    border-radius: 6px;
    padding: 0 14px;
    background: rgba(8, 18, 32, 0.72);
    color: #eff5fc;
    font-size: 0.86rem;
    outline: none;
}

.reference-add-house {
    height: 40px;
    border: 0;
    border-radius: 7px;
    background: #ff243d;
    color: #fff;
    font-size: 0.82rem;
    font-weight: 900;
    box-shadow: 0 10px 20px rgba(255, 36, 61, 0.2);
}

.reference-house-actions {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: 8px;
}

.reference-house-actions:has(.reference-cancel-house) {
    grid-template-columns: minmax(0, 1fr) minmax(82px, 0.74fr);
}

.reference-cancel-house {
    height: 40px;
    border: 1px solid rgba(139, 161, 196, 0.24);
    border-radius: 7px;
    background: rgba(8, 18, 32, 0.48);
    color: #d7e1ee;
    font-size: 0.78rem;
    font-weight: 850;
}

.reference-toolbar .house-feedback {
    position: static;
    grid-column: 1 / 4;
    width: 100%;
    min-height: 34px;
    height: auto;
    padding: 8px 12px;
    border-radius: 8px;
    font-size: 0.78rem;
    font-weight: 700;
    line-height: 1.3;
}

.reference-toolbar .house-feedback.success {
    background: rgba(34, 197, 94, 0.11);
    color: #86efac;
    border: 1px solid rgba(34, 197, 94, 0.24);
}

.reference-toolbar .house-feedback.error {
    background: rgba(255, 36, 61, 0.11);
    color: #ff8a9a;
    border: 1px solid rgba(255, 36, 61, 0.26);
}

.reference-month {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.reference-house-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 16px;
    padding-top: 16px;
}

.reference-house-card {
    min-height: 146px;
    position: relative;
    overflow: hidden;
    border: 1px solid rgba(139, 161, 196, 0.13);
    border-radius: 15px;
    padding: 17px 18px;
    background: linear-gradient(180deg, rgba(21, 34, 55, 0.94), rgba(14, 27, 46, 0.98));
    box-shadow: 0 14px 28px rgba(0, 0, 0, 0.18);
}

.reference-house-card.active {
    border-color: #ff243d;
    box-shadow: inset 0 0 0 1px rgba(255, 36, 61, 0.28), 0 14px 28px rgba(0, 0, 0, 0.2);
}

.reference-house-card header {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.reference-house-card header strong {
    font-size: 0.98rem;
    font-weight: 900;
}

.reference-house-card header span,
.reference-house-card header span::before,
.reference-house-card header span::after {
    width: 3px;
    height: 3px;
    border-radius: 999px;
    background: #c5d0dd;
}

.reference-house-card header span {
    position: relative;
    display: block;
}

.reference-house-card header span::before,
.reference-house-card header span::after {
    content: "";
    position: absolute;
    left: 0;
}

.reference-house-card header span::before {
    top: -6px;
}

.reference-house-card header span::after {
    top: 6px;
}

.reference-edit-house {
    position: relative;
    z-index: 2;
    min-height: 28px;
    border: 1px solid rgba(139, 161, 196, 0.2);
    border-radius: 7px;
    padding: 0 9px;
    background: rgba(8, 18, 32, 0.42);
    color: #cbd8e8;
    font-size: 0.72rem;
    font-weight: 850;
}

.reference-house-card dl {
    display: grid;
    gap: 5px;
    margin: 28px 0 0;
}

.reference-house-card dl div {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.reference-house-card dt {
    color: #9dafc5;
    font-size: 0.84rem;
    font-weight: 700;
}

.reference-house-card dd {
    margin: 0;
    color: #f3f7fc;
    font-size: 0.95rem;
    font-weight: 900;
}

.reference-sparkline {
    position: absolute;
    left: 18px;
    right: 18px;
    bottom: 15px;
    height: 24px;
    opacity: 0.96;
    clip-path: polygon(0 78%, 9% 68%, 16% 85%, 28% 64%, 39% 50%, 52% 62%, 60% 67%, 70% 42%, 78% 50%, 88% 55%, 100% 52%, 100% 100%, 0 100%);
}

.reference-sparkline.red {
    background: linear-gradient(180deg, rgba(255, 48, 72, 0.9), rgba(255, 48, 72, 0.08));
    border-top: 2px solid #ff3048;
}

.reference-sparkline.green {
    background: linear-gradient(180deg, rgba(40, 209, 124, 0.9), rgba(40, 209, 124, 0.08));
    border-top: 2px solid #28d17c;
}

.reference-kpi-row {
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    gap: 16px;
    margin-top: 16px;
}

.reference-kpi-card {
    min-height: 128px;
    display: grid;
    grid-template-columns: 54px minmax(0, 1fr);
    gap: 14px;
    align-items: start;
    border: 1px solid rgba(139, 161, 196, 0.14);
    border-radius: 14px;
    padding: 18px;
    background: linear-gradient(180deg, rgba(19, 33, 55, 0.95), rgba(13, 26, 45, 0.99));
    box-shadow: 0 14px 30px rgba(0, 0, 0, 0.2);
}

.reference-kpi-icon {
    width: 54px;
    height: 54px;
    border-radius: 999px;
    background: rgba(112, 130, 164, 0.28);
}

.reference-kpi-icon.trend {
    background: rgba(255, 48, 72, 0.26);
}

.reference-kpi-icon.target {
    background: rgba(40, 209, 124, 0.28);
}

.reference-kpi-icon.percent {
    background: rgba(154, 69, 255, 0.3);
}

.reference-kpi-icon.wallet {
    background: rgba(255, 155, 22, 0.28);
}

.reference-kpi-icon::before {
    inset: 15px;
    border: 2px solid #edf3fb;
    border-radius: 5px;
}

.reference-kpi-icon.target::before,
.reference-kpi-icon.percent::before {
    border-radius: 999px;
}

.reference-kpi-card small {
    display: block;
    margin-top: 2px;
    color: #9baabe;
    font-size: 0.78rem;
    font-weight: 800;
}

.reference-kpi-card strong {
    display: block;
    margin-top: 8px;
    color: #f7fbff;
    font-size: 1.45rem;
    font-weight: 950;
    letter-spacing: -0.04em;
    line-height: 1.1;
}

.reference-kpi-card.positive strong {
    color: #6ed8a8;
}

.reference-kpi-card.negative strong {
    color: #ff6f7f;
}

.reference-kpi-card p {
    margin: 10px 0 0;
    color: #98a8bd;
    font-size: 0.75rem;
    font-weight: 700;
}

.reference-analytics-grid {
    display: grid;
    grid-template-columns: 1.04fr 0.98fr 1.12fr;
    gap: 16px;
    margin-top: 16px;
}

.reference-analytics-panel {
    min-height: 310px;
    overflow: hidden;
    border: 1px solid rgba(139, 161, 196, 0.14);
    border-radius: 15px;
    padding: 20px 22px;
    background: linear-gradient(180deg, rgba(16, 29, 50, 0.96), rgba(10, 22, 39, 0.98));
    box-shadow: 0 16px 36px rgba(0, 0, 0, 0.22);
}

.reference-analytics-panel header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    margin-bottom: 14px;
}

.reference-analytics-panel h2 {
    margin: 0;
    color: #f1f6fd;
    font-size: 0.95rem;
    font-weight: 900;
}

.reference-analytics-panel header button {
    min-width: 112px;
    height: 38px;
    border: 1px solid rgba(139, 161, 196, 0.22);
    border-radius: 6px;
    background: rgba(8, 18, 32, 0.68);
    color: #cdd8e8;
    font-size: 0.78rem;
    font-weight: 800;
}

.reference-area-chart {
    position: relative;
    height: 235px;
    padding-left: 54px;
    background: linear-gradient(rgba(139, 161, 196, 0.11) 1px, transparent 1px) 54px 18px / calc(100% - 54px) 39px;
}

.reference-area-chart svg {
    position: absolute;
    inset: 8px 0 18px 54px;
    width: calc(100% - 54px);
    height: calc(100% - 26px);
}

.reference-area-chart .fill {
    fill: url(#referenceAreaFill);
}

.reference-area-chart .line {
    fill: none;
    stroke: #ff3048;
    stroke-width: 4;
}

.reference-area-chart circle {
    fill: #ff3048;
    stroke: #fff;
    stroke-width: 4;
}

.reference-area-chart .y,
.reference-area-chart .x {
    position: absolute;
    color: #98a8bd;
    font-size: 0.72rem;
    font-weight: 700;
}

.reference-area-chart .y {
    left: 0;
}

.reference-area-chart .y1 { top: 15px; }
.reference-area-chart .y2 { top: 54px; }
.reference-area-chart .y3 { top: 93px; }
.reference-area-chart .y4 { top: 132px; }
.reference-area-chart .y5 { top: 171px; }
.reference-area-chart .x { bottom: 0; }
.reference-area-chart .x1 { left: 62px; }
.reference-area-chart .x2 { left: 27%; }
.reference-area-chart .x3 { left: 43%; }
.reference-area-chart .x4 { left: 62%; }
.reference-area-chart .x5 { right: 0; }

.reference-bar-chart {
    height: 226px;
    display: grid;
    grid-template-columns: repeat(6, 1fr);
    align-items: end;
    gap: 22px;
    margin-top: 12px;
    padding: 0 18px 27px;
    border-bottom: 1px solid rgba(139, 161, 196, 0.18);
    background: linear-gradient(rgba(139, 161, 196, 0.1) 1px, transparent 1px) 0 0 / 100% 39px;
}

.reference-bar-chart span {
    min-height: 24px;
    border-radius: 4px 4px 0 0;
}

.reference-bar-chart .pos {
    background: linear-gradient(180deg, rgba(40, 209, 124, 0.95), rgba(40, 209, 124, 0.34));
}

.reference-bar-chart .neg {
    background: linear-gradient(180deg, rgba(255, 48, 72, 0.95), rgba(255, 48, 72, 0.32));
}

.reference-donut-layout {
    display: grid;
    grid-template-columns: 186px minmax(0, 1fr);
    align-items: center;
    gap: 42px;
    min-height: 230px;
}

.reference-donut {
    width: 186px;
    aspect-ratio: 1;
    border-radius: 999px;
    background:
        radial-gradient(circle, #0e1c31 0 46%, transparent 47%),
        conic-gradient(#70c844 0 28%, #4f8cff 28% 64%, #ff8d0a 64% 91%, #5d6878 91% 100%);
    box-shadow: inset 0 0 28px rgba(0, 0, 0, 0.25), 0 16px 32px rgba(0, 0, 0, 0.18);
}

.reference-legend {
    display: grid;
    gap: 24px;
}

.reference-legend span {
    display: grid;
    grid-template-columns: 12px minmax(0, 1fr) 70px;
    align-items: center;
    gap: 12px;
    color: #e1e8f2;
    font-size: 0.82rem;
    font-weight: 700;
}

.reference-legend i {
    width: 12px;
    height: 12px;
    border-radius: 999px;
}

.reference-legend b {
    justify-self: end;
    font-size: 0.82rem;
}

.reference-legend .green { background: #28d17c; }
.reference-legend .blue { background: #4f8cff; }
.reference-legend .orange { background: #ff9b16; }
.reference-legend .gray { background: #5d6878; }

.reference-actions {
    margin-top: 16px;
    border: 1px solid rgba(139, 161, 196, 0.14);
    border-radius: 15px;
    padding: 16px 20px;
    background: linear-gradient(180deg, rgba(16, 29, 50, 0.96), rgba(10, 22, 39, 0.98));
}

.reference-actions h2 {
    margin: 0 0 13px;
    color: #eaf0f8;
    font-size: 0.9rem;
    font-weight: 900;
}

.reference-actions > div {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 28px;
}

.reference-actions button {
    min-height: 62px;
    display: grid;
    grid-template-columns: 32px minmax(0, 1fr) 26px;
    align-items: center;
    gap: 12px;
    border: 1px solid rgba(139, 161, 196, 0.14);
    border-radius: 11px;
    padding: 12px 14px;
    background: linear-gradient(180deg, rgba(21, 34, 55, 0.94), rgba(15, 27, 46, 0.98));
    color: #eaf0f8;
    text-align: left;
}

.reference-action-icon {
    width: 32px;
    height: 32px;
    border-radius: 9px;
    background: rgba(139, 161, 196, 0.13);
}

.reference-action-icon::before {
    inset: 8px 9px 7px;
    border: 1.6px solid #c9d5e6;
    border-radius: 3px;
}

.reference-actions strong {
    font-size: 0.86rem;
    font-weight: 900;
}

.reference-actions button > i {
    width: 26px;
    height: 26px;
    display: grid;
    place-items: center;
    border: 1px solid rgba(139, 161, 196, 0.22);
    border-radius: 999px;
    color: #d6dfec;
    font-style: normal;
    font-weight: 500;
}

@media (max-width: 1200px) {
    .reference-dashboard {
        grid-template-columns: 260px minmax(0, 1fr);
    }

    .reference-sidebar {
        padding-inline: 12px;
    }

    .reference-toolbar {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .reference-toolbar-spacer {
        display: none;
    }

    .reference-house-grid,
    .reference-kpi-row,
    .reference-analytics-grid,
    .reference-actions > div {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@media (max-width: 768px) {
    .reference-dashboard {
        display: block;
    }

    .reference-sidebar {
        position: static;
        height: auto;
        padding: 20px 14px;
    }

    .reference-upgrade-card {
        display: none;
    }

    .reference-main {
        padding: 16px 14px 24px;
    }

    .reference-header,
    .reference-toolbar {
        display: grid;
    }

    .reference-toolbar,
    .reference-house-grid,
    .reference-kpi-row,
    .reference-analytics-grid,
    .reference-actions > div,
    .reference-donut-layout {
        grid-template-columns: 1fr;
    }
