.cb-donut-chart {
    width: 150px;
    height: 150px;
    display: grid;
    place-items: center;
    border-radius: 999px;
    background: conic-gradient(#22c55e 0 28%, #3b82f6 28% 64%, #f59e0b 64% 95%, #64748b 95% 100%);
    box-shadow: 0 20px 40px rgba(0, 0, 0, 0.22);
}

.cb-donut-chart::before {
    content: "";
    width: 82px;
    height: 82px;
    border-radius: inherit;
    background: #0f172a;
}

.cb-donut-chart span {
    display: none;
}

.cb-donut-legend {
    display: grid;
    gap: 16px;
}

.cb-donut-legend div {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    gap: 10px;
}

.cb-donut-legend span {
    min-width: 0;
    display: flex;
    align-items: center;
    gap: 10px;
    overflow: hidden;
    color: #f8fafc;
    font-size: 0.82rem;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.cb-donut-legend i {
    width: 10px;
    height: 10px;
    flex: 0 0 auto;
    border-radius: 999px;
}

.cb-donut-legend strong {
    color: #f8fafc;
    font-size: 0.82rem;
    font-variant-numeric: tabular-nums;
}

.color-0 { background: #22c55e; }
.color-1 { background: #3b82f6; }
.color-2 { background: #f59e0b; }
.color-other { background: #64748b; }

.cb-quick-actions-panel {
    display: grid;
    gap: 14px;
}

.cb-quick-actions-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 24px;
}

.cb-quick-action-card {
    min-height: 64px;
    display: grid;
    grid-template-columns: 36px minmax(0, 1fr) 32px;
    align-items: center;
    gap: 14px;
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 10px;
    padding: 12px 16px;
    background: rgba(15, 23, 42, 0.68);
    color: #f8fafc;
    font: inherit;
    cursor: pointer;
}

.cb-quick-action-card span {
    width: 34px;
    height: 34px;
    display: grid;
    place-items: center;
    border-radius: 10px;
    background: rgba(148, 163, 184, 0.12);
    color: #cbd5e1;
}

.cb-quick-action-card strong {
    min-width: 0;
    overflow: hidden;
    color: #f8fafc;
    font-size: 0.9rem;
    text-align: left;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.cb-quick-action-card i {
    width: 30px;
    height: 30px;
    display: grid;
    place-items: center;
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 999px;
    color: #cbd5e1;
    font-style: normal;
}

