/* ===== CONTROLBET DASHBOARD STRUCTURE REBUILD ===== */

.reference-dashboard {
    --cb-bg: var(--cb-theme-background);
    --cb-surface: var(--cb-theme-surface);
    --cb-surface-soft: var(--cb-theme-surface-secondary);
    --cb-border: var(--cb-theme-border);
    --cb-border-strong: var(--cb-theme-divider);
    --cb-text: var(--cb-theme-text-primary);
    --cb-muted: var(--cb-theme-text-muted);
    --cb-red: var(--cb-theme-danger);
    --cb-green: var(--cb-theme-success);
    --cb-blue: var(--cb-theme-info);
    background: var(--cb-bg);
    color: var(--cb-text);
}

.reference-dashboard[data-theme="dark"] {
    --cb-bg: var(--cb-theme-background);
    --cb-surface: var(--cb-theme-surface);
    --cb-surface-soft: var(--cb-theme-surface-secondary);
    --cb-border: var(--cb-theme-border);
    --cb-border-strong: var(--cb-theme-divider);
    --cb-text: var(--cb-theme-text-primary);
    --cb-muted: var(--cb-theme-text-muted);
}

.reference-main {
    min-width: 0;
}

.cb-dashboard-home {
    display: grid;
    gap: 14px;
    width: 100%;
    min-width: 0;
}

.cb-topbar-card,
.cb-panel,
.cb-summary-card,
.cb-house-card {
    background: var(--cb-surface);
    border: 1px solid var(--cb-border);
    box-shadow: 0 12px 28px rgba(15, 23, 42, 0.06);
}

.reference-dashboard[data-theme="dark"] .cb-topbar-card,
.reference-dashboard[data-theme="dark"] .cb-panel,
.reference-dashboard[data-theme="dark"] .cb-summary-card,
.reference-dashboard[data-theme="dark"] .cb-house-card {
    box-shadow: 0 22px 54px rgba(0, 0, 0, 0.26);
}

.cb-topbar-card {
    position: relative;
    z-index: 4;
    display: grid;
    grid-template-columns: minmax(170px, 1fr) minmax(150px, 180px) minmax(150px, 190px) minmax(132px, 150px) minmax(140px, 170px) auto;
    align-items: end;
    gap: 18px;
    min-height: 88px;
    border-radius: 14px;
    padding: 18px 20px;
}

.cb-topbar-field,
.cb-topbar-card .reference-period {
    min-width: 0;
    display: grid;
    gap: 7px;
}

.cb-topbar-field > span,
.cb-topbar-card .reference-period > span {
    color: var(--cb-muted);
    font-size: 0.74rem;
    font-weight: 800;
    line-height: 1.1;
}

.cb-topbar-field input,
.cb-house-select-trigger,
.cb-topbar-card .reference-period select,
.cb-topbar-card .reference-selector-surface {
    width: 100%;
    height: 42px !important;
    min-height: 42px !important;
    border: 1px solid var(--cb-border-strong) !important;
    border-radius: 10px !important;
    background: var(--cb-surface-soft) !important;
    color: var(--cb-text) !important;
    box-shadow: none !important;
    font: inherit;
    font-size: 0.88rem !important;
    font-weight: 800;
}

.cb-topbar-field input {
    padding: 0 12px !important;
}

.cb-house-select-wrap {
    position: relative;
}

.cb-house-select-trigger {
    display: grid;
    grid-template-columns: 28px minmax(0, 1fr) auto;
    align-items: center;
    gap: 10px;
    padding: 0 12px;
    text-align: left;
    cursor: pointer;
}

.cb-house-select-trigger i,
.cb-house-avatar {
    display: inline-grid;
    place-items: center;
    border-radius: 999px;
    background: linear-gradient(135deg, #16c172, #0aa365);
    color: #fff;
    font-style: normal;
    font-weight: 900;
}

.cb-house-select-trigger i {
    width: 26px;
    height: 26px;
    font-size: 0.74rem;
}

.cb-house-select-trigger strong {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.cb-house-select-trigger em {
    color: var(--cb-muted);
    font-style: normal;
}

.cb-house-select-menu {
    position: absolute;
    top: calc(100% + 8px);
    left: 0;
    z-index: 40;
    width: min(260px, 90vw);
    display: grid;
    gap: 5px;
