    font-weight: 800;
}

.cb-financial-list {
    display: grid;
    gap: 12px;
}

.cb-financial-list div {
    min-height: 42px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 14px;
    border-radius: 10px;
    padding: 0 12px;
