}

.cb-financial-list span {
    color: var(--cb-text);
    font-size: 0.78rem;
    font-weight: 850;
}

.cb-financial-list strong {
    color: var(--cb-text);
    font-size: 0.78rem;
    font-weight: 900;
    text-align: right;
}

.cb-latest-tickets-card {
    display: grid;
    gap: 10px;
}

.cb-latest-table {
    min-width: 0;
    overflow-x: auto;
}

.cb-latest-head,
.cb-latest-row {
    display: grid;
    grid-template-columns: 100px minmax(110px, 1fr) minmax(130px, 1.2fr) 70px 110px 110px 100px;
    align-items: center;
    gap: 10px;
    min-width: 820px;
}

.cb-latest-head {
    min-height: 32px;
    border-bottom: 1px solid var(--cb-border);
    color: var(--cb-muted);
    font-size: 0.72rem;
    font-weight: 900;
}

.cb-latest-row {
    min-height: 42px;
    border-bottom: 1px solid var(--cb-border);
    color: var(--cb-text);
    font-size: 0.78rem;
    font-weight: 800;
}

.cb-latest-row strong {
    width: fit-content;
    border: 1px solid currentColor;
    border-radius: 7px;
    padding: 4px 9px;
    font-size: 0.72rem;
    font-weight: 900;
}

.cb-latest-empty {
    min-height: 74px;
    display: grid;
    place-items: center;
    color: var(--cb-muted);
    font-size: 0.82rem;
    font-weight: 800;
}

.cb-latest-action {
    justify-self: stretch;
}

@media (max-width: 1280px) {
    .cb-topbar-card {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .cb-topbar-icons {
        justify-content: flex-start;
    }

    .cb-summary-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@media (max-width: 980px) {
    .cb-topbar-card,
    .cb-main-grid,
    .cb-bottom-grid,
    .cb-summary-grid {
        grid-template-columns: 1fr;
    }

    .cb-house-carousel {
        grid-template-columns: 1fr;
    }

    .cb-carousel-arrow {
        display: none;
    }

    .cb-house-track {
        grid-auto-columns: minmax(150px, 58vw);
    }

    .cb-summary-card {
        grid-template-columns: 48px minmax(0, 1fr) 74px;
    }

    .cb-quick-summary-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 14px 0;
    }
}

