        min-width: 0 !important;
        width: 100% !important;
    }

    .reference-dashboard .cb-topbar-card input,
    .reference-dashboard .cb-topbar-card select,
    .reference-dashboard .cb-topbar-card .reference-selector-surface,
    .reference-dashboard .cb-topbar-card .reference-period button {
        width: 100% !important;
        min-width: 0 !important;
        height: 44px !important;
        min-height: 44px !important;
    }

    .reference-dashboard .cb-add-house-button {
        width: auto !important;
        min-width: 160px !important;
        height: 44px !important;
        min-height: 44px !important;
        white-space: nowrap !important;
    }

    .reference-dashboard .cb-house-feedback {
        grid-column: 1 / -1 !important;
    }

    .reference-dashboard .cb-house-carousel {
        display: block !important;
        overflow: visible !important;
    }

    .reference-dashboard .cb-house-track {
        display: flex !important;
        grid-template-columns: none !important;
        gap: 16px !important;
        width: 100% !important;
        max-width: none !important;
        min-width: 0 !important;
        overflow-x: auto !important;
        overflow-y: visible !important;
        padding: 0 0 10px !important;
        scroll-snap-type: x proximity !important;
        scrollbar-gutter: stable !important;
    }

    .reference-dashboard .cb-house-card,
    .reference-dashboard .cb-house-card:not(.cb-house-all-card) {
        flex: 0 0 280px !important;
        flex-shrink: 0 !important;
        width: 280px !important;
        min-width: 280px !important;
        max-width: 280px !important;
        height: 150px !important;
        min-height: 150px !important;
        scroll-snap-align: start !important;
    }

    .reference-dashboard .cb-house-all-card {
        flex: 0 0 320px !important;
        width: 320px !important;
        min-width: 320px !important;
        max-width: 320px !important;
    }

    .reference-dashboard .cb-house-card-main {
        height: 100% !important;
        min-height: 0 !important;
        overflow: hidden !important;
    }

    .reference-dashboard .cb-house-card,
    .reference-dashboard .cb-house-card-main,
    .reference-dashboard .cb-house-card-head,
    .reference-dashboard .cb-house-stats,
    .reference-dashboard .cb-house-stats span {
        min-width: 0 !important;
    }

    .reference-dashboard .cb-house-card-head strong {
        min-width: 0 !important;
        overflow: hidden !important;
        text-overflow: ellipsis !important;
        white-space: nowrap !important;
    }

    .reference-dashboard .cb-house-stats span,
    .reference-dashboard .cb-house-stats b {
        overflow: hidden !important;
        text-overflow: ellipsis !important;
        white-space: normal !important;
    }

    .reference-dashboard .cb-summary-grid {
        grid-template-columns: repeat(5, minmax(0, 1fr)) !important;
    }

    .reference-dashboard .cb-main-grid {
        grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) minmax(0, 1fr) !important;
    }
}

@media (min-width: 981px) and (max-width: 1280px) {
    .reference-dashboard .cb-topbar-card {
        grid-template-columns: 190px 180px auto 160px 160px !important;
        gap: 14px !important;
    }

    .reference-dashboard .cb-add-house-button {
        min-width: 138px !important;
    }
}

/* ===== LIGHT DASHBOARD STRUCTURE ===== */

html:has(.dark-dashboard-shell),
body:has(.dark-dashboard-shell),
#root:has(.dark-dashboard-shell),
.app:has(.dark-dashboard-shell) {
    width: 100%;
    max-width: none;
    min-height: 100%;
    margin: 0;
    padding: 0;
    overflow-x: hidden;
    background:
        radial-gradient(circle at 8% 0%, rgba(225, 29, 46, 0.08), transparent 28%),
        radial-gradient(circle at 92% 4%, rgba(56, 189, 248, 0.10), transparent 30%),
        linear-gradient(135deg, #f7f9fc 0%, #eef3f8 52%, #e7edf5 100%);
}

.dark-dashboard-shell {
    --dark-sidebar-width: 268px;
    width: 100%;
    min-height: 100vh;
    display: grid;
    grid-template-columns: var(--dark-sidebar-width) minmax(0, 1fr);
    background:
        radial-gradient(circle at 12% -4%, rgba(225, 29, 46, 0.08), transparent 26%),
        radial-gradient(circle at 86% 0%, rgba(56, 189, 248, 0.10), transparent 30%),
        linear-gradient(135deg, #f7f9fc 0%, #eef3f8 52%, #e7edf5 100%);
    color: #0f172a;
}

.dark-dashboard-sidebar {
    position: sticky;
    top: 0;
    height: 100vh;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    gap: 18px;
    padding: 24px 18px;
    border-right: 1px solid rgba(203, 213, 225, 0.86);
    background:
        radial-gradient(circle at 0% 0%, rgba(225, 29, 46, 0.055), transparent 34%),
        linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.96));
    box-shadow: 16px 0 38px rgba(15, 23, 42, 0.06);
}

.dark-dashboard-sidebar .reference-brand-logo {
    display: flex;
    align-items: center;
    min-height: 70px;
}

.dark-dashboard-sidebar .reference-brand-logo img {
    width: 142px;
    height: auto;
    object-fit: contain;
    filter: drop-shadow(0 14px 26px rgba(15, 23, 42, 0.10));
}

.dark-dashboard-sidebar .reference-sidebar-welcome {
    margin: 0;
    color: #64748b;
    font-size: 0.78rem;
    font-weight: 750;
}

.dark-dashboard-sidebar .reference-nav {
    display: grid;
    gap: 7px;
}

.dark-dashboard-sidebar .reference-nav-group {
    display: grid;
    gap: 6px;
}

.dark-dashboard-sidebar .reference-nav-item {
    min-height: 44px;
    display: flex;
    align-items: center;
    gap: 10px;
    border: 1px solid transparent;
    border-radius: 14px;
    padding: 0 11px;
    background: transparent;
    color: #64748b;
    font: inherit;
    font-size: 0.82rem;
    font-weight: 850;
    text-align: left;
    cursor: pointer;
}

.dark-dashboard-sidebar .reference-nav-item.active,
.dark-dashboard-sidebar .reference-nav-item:hover {
    border-color: rgba(225, 29, 46, 0.18);
    background: linear-gradient(180deg, #fff7f7, #ffffff);
    color: #0f172a;
}

.dark-dashboard-sidebar .ref-icon {
    width: 30px;
    height: 30px;
    display: inline-grid;
    place-items: center;
    flex: 0 0 30px;
    border-radius: 10px;
    background: #eef2f7;
    color: #475569;
}

.dark-dashboard-sidebar .ref-icon-svg {
    width: 17px;
    height: 17px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.8;
}

.dark-dashboard-sidebar .reference-nav-subitems,
.dark-dashboard-sidebar .reference-sidebar-footer {
    display: none;
}

.dark-dashboard-sidebar .reference-sidebar-plan {
    margin-top: auto;
    display: grid;
    gap: 9px;
    border: 1px solid rgba(203, 213, 225, 0.82);
    border-radius: 18px;
    padding: 15px;
    background: linear-gradient(180deg, #ffffff, #f8fafc);
}

.dark-dashboard-sidebar .reference-sidebar-plan strong,
.dark-dashboard-sidebar .reference-sidebar-plan b {
    color: #0f172a;
    font-size: 0.84rem;
}

.dark-dashboard-sidebar .reference-sidebar-plan span,
.dark-dashboard-sidebar .reference-sidebar-plan p {
    margin: 0;
    color: #64748b;
    font-size: 0.72rem;
}

.dark-dashboard-sidebar .reference-sidebar-plan button {
    min-height: 34px;
    border: 1px solid rgba(248, 113, 113, 0.28);
    border-radius: 10px;
    background: linear-gradient(180deg, #f43f5e, #d91f2e);
    color: #ffffff;
    font: inherit;
    font-size: 0.74rem;
    font-weight: 900;
    cursor: pointer;
}

.dark-dashboard-sidebar .reference-sidebar-promo {
    display: none;
}

.dark-dashboard-main {
    min-width: 0;
    width: 100%;
    padding: 24px 28px 34px;
    background: transparent;
}

.dark-dashboard-home {
    display: grid;
    gap: 18px;
    width: 100%;
    min-width: 0;
}

.dark-dashboard-header {
    min-height: 68px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 18px;
}

.dark-dashboard-header span {
    display: block;
    color: #e11d2e;
    font-size: 0.68rem;
    font-weight: 900;
    letter-spacing: 0.08em;
    text-transform: uppercase;
}

.dark-dashboard-header h1 {
    margin: 4px 0 0;
    color: #0f172a;
    font-size: clamp(2rem, 2.6vw, 2.8rem);
    line-height: 1;
}

.dark-dashboard-header p {
    margin: 5px 0 0;
    color: #64748b;
    font-size: 0.9rem;
    font-weight: 700;
}

.dark-dashboard-profile {
    min-width: 240px;
    display: flex;
    align-items: center;
    gap: 11px;
    border: 1px solid rgba(203, 213, 225, 0.88);
    border-radius: 18px;
    padding: 9px 12px;
    background: rgba(255, 255, 255, 0.92);
}

.dark-dashboard-profile i {
    width: 38px;
    height: 38px;
    display: inline-grid;
    place-items: center;
    border-radius: 999px;
    background: linear-gradient(135deg, #e11d2e, #b91c1c);
    color: #ffffff;
    font-style: normal;
    font-size: 0.78rem;
    font-weight: 900;
}

.dark-dashboard-profile strong,
.dark-dashboard-profile small {
    display: block;
}

.dark-dashboard-profile strong {
    max-width: 150px;
    overflow: hidden;
    color: #0f172a;
    font-size: 0.82rem;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.dark-dashboard-profile small {
    color: #64748b;
    font-size: 0.68rem;
    font-weight: 800;
}

.dark-dashboard-panel {
    width: 100%;
    display: grid;
    gap: 16px;
    border: 1px solid rgba(203, 213, 225, 0.88);
    border-radius: 16px;
    padding: 18px 22px 20px;
    background:
        radial-gradient(circle at 0% 0%, rgba(225, 29, 46, 0.045), transparent 34%),
        linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.96));
    box-shadow:
        0 18px 42px rgba(15, 23, 42, 0.08),
        inset 0 1px 0 rgba(255, 255, 255, 0.82);
}

.dark-filter-row {
    display: grid;
    grid-template-columns: minmax(170px, 1fr) minmax(150px, 0.82fr) 140px 150px 170px;
    gap: 14px;
    align-items: end;
    width: 100%;
    padding-bottom: 16px;
    border-bottom: 1px solid rgba(203, 213, 225, 0.78);
}

.dark-filter-field {
    min-width: 0;
    display: grid;
    gap: 6px;
    color: #475569;
    font-size: 0.72rem;
    font-weight: 800;
    line-height: 1;
}

.dark-filter-field input,
.dark-filter-field select {
    width: 100%;
    height: 38px !important;
    min-height: 38px !important;
    border: 1px solid rgba(203, 213, 225, 0.95) !important;
    border-radius: 6px !important;
    padding: 0 11px !important;
    background: #ffffff !important;
    color: #0f172a !important;
    font-size: 0.84rem !important;
    font-weight: 750 !important;
    box-shadow: none !important;
}

.dark-filter-field input::placeholder {
    color: #94a3b8;
    opacity: 1;
}

.dark-filter-actions {
    display: flex;
    align-items: end;
    gap: 8px;
    min-width: 0;
}

.dark-add-house-button,
.dark-cancel-house-button {
    height: 38px;
    border-radius: 6px;
    padding: 0 13px;
    font: inherit;
    font-size: 0.8rem;
    font-weight: 900;
    white-space: nowrap;
    cursor: pointer;
}

.dark-add-house-button {
    border: 1px solid rgba(248, 113, 113, 0.34);
    background: linear-gradient(180deg, #ff304b, #e31c34);
    color: #ffffff;
    box-shadow: 0 12px 26px rgba(255, 36, 72, 0.2);
}

.dark-cancel-house-button {
    border: 1px solid rgba(203, 213, 225, 0.95);
    background: #ffffff;
    color: #475569;
}

.dark-house-feedback {
    grid-column: 1 / -1;
    min-height: 34px;
    display: flex;
    align-items: center;
    border-radius: 8px;
    padding: 8px 10px;
    font-size: 0.78rem;
    font-weight: 800;
}

.dark-house-feedback.success {
    border: 1px solid rgba(74, 222, 128, 0.28);
    background: #f0fdf4;
    color: #166534;
}

.dark-house-feedback.error {
    border: 1px solid rgba(251, 113, 133, 0.3);
    background: #fff7f7;
    color: #991b1b;
}

.dark-house-row {
    position: relative;
    display: grid;
    grid-auto-flow: column;
    grid-auto-columns: calc((100% - 42px) / 4);
    gap: 14px;
    width: 100%;
    overflow-x: auto;
    overflow-y: hidden;
    padding-bottom: 12px;
    scroll-snap-type: x proximity;
    scrollbar-gutter: stable;
}

.dark-house-row::-webkit-scrollbar {
    height: 8px;
}

.dark-house-row::-webkit-scrollbar-track {
    border-radius: 999px;
    background: rgba(203, 213, 225, 0.62);
}

.dark-house-row::-webkit-scrollbar-thumb {
    border-radius: 999px;
    background: rgba(100, 116, 139, 0.46);
}

.dark-house-row::-webkit-scrollbar-thumb:hover {
    background: rgba(71, 85, 105, 0.62);
}

.dark-house-card {
    position: relative;
    min-width: 0;
    min-height: 106px;
    overflow: hidden;
    border: 1px solid rgba(203, 213, 225, 0.88);
    border-radius: 14px;
    background:
        radial-gradient(circle at 0% 0%, rgba(225, 29, 46, 0.035), transparent 34%),
        linear-gradient(180deg, #ffffff, #f8fafc);
    box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.82),
        0 12px 26px rgba(15, 23, 42, 0.07);
    scroll-snap-align: start;
}

.dark-house-card.selected {
    border-color: #ff2448;
    box-shadow:
        0 0 0 1px rgba(255, 36, 72, 0.34) inset,
        0 14px 30px rgba(225, 29, 46, 0.08);
}

.dark-house-card-main,
.dark-house-card-add {
    width: 100%;
    height: 100%;
    min-height: 106px;
    display: grid;
    gap: 7px;
    border: 0;
    padding: 13px 16px 12px;
    background: transparent;
    color: inherit;
    font: inherit;
    text-align: left;
    cursor: pointer;
}

.dark-house-card-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
}

.dark-house-card-head strong {
    min-width: 0;
    overflow: hidden;
    color: #0f172a;
    font-size: 1rem;
    line-height: 1.12;
    font-weight: 900;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.dark-house-stats {
    align-self: end;
    display: grid;
    gap: 5px;
}

.dark-house-stats span {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    color: #64748b;
    font-size: 0.84rem;
    line-height: 1.2;
    font-weight: 650;
}

.dark-house-stats b {
    color: #0f172a;
    font-size: 0.94rem;
    font-weight: 900;
}

.dark-house-sparkline {
    display: none;
}

.dark-house-sparkline.positive {
    opacity: 0.9;
}

.dark-house-menu-button {
    position: absolute;
    top: 10px;
    right: 10px;
    width: 26px;
    height: 26px;
    border: 0;
    border-radius: 8px;
    background: #eef2f7;
    color: #64748b;
    cursor: pointer;
}

.dark-house-menu {
    position: absolute;
    top: 38px;
    right: 10px;
    z-index: 20;
    display: grid;
    gap: 5px;
    min-width: 110px;
    border: 1px solid rgba(203, 213, 225, 0.94);
    border-radius: 10px;
    padding: 6px;
    background: #ffffff;
    box-shadow: 0 18px 36px rgba(15, 23, 42, 0.12);
}

.dark-house-menu button {
    min-height: 30px;
    border: 0;
    border-radius: 7px;
    background: transparent;
    color: #334155;
    font: inherit;
    font-size: 0.74rem;
    font-weight: 850;
    text-align: left;
    cursor: pointer;
}

.dark-house-menu button:hover {
    background: #fff1f2;
}

.dark-house-menu button.danger {
    color: #b91c1c;
}

.dark-kpi-grid {
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    gap: 14px;
    width: 100%;
}

.dark-kpi-card {
    min-height: 122px;
    display: grid;
    grid-template-columns: 48px minmax(0, 1fr);
    align-items: center;
    gap: 15px;
    overflow: hidden;
    border: 1px solid rgba(203, 213, 225, 0.88);
    border-radius: 14px;
    padding: 17px 18px;
    background:
        radial-gradient(circle at 0% 0%, rgba(225, 29, 46, 0.035), transparent 34%),
        linear-gradient(180deg, #ffffff, #f8fafc);
    box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.82),
        0 12px 26px rgba(15, 23, 42, 0.07);
}

.dark-kpi-icon {
    width: 48px;
    height: 48px;
    display: inline-grid;
    place-items: center;
    border: 1px solid rgba(203, 213, 225, 0.92);
    border-radius: 999px;
    background: #eef2f7;
    color: #475569;
}

.dark-kpi-icon .reference-kpi-svg {
    width: 22px;
    height: 22px;
}

.dark-kpi-copy {
    min-width: 0;
}

.dark-kpi-copy small,
.dark-kpi-copy em {
    display: block;
    color: #64748b;
    font-size: 0.74rem;
    line-height: 1.2;
    font-style: normal;
    font-weight: 750;
}

.dark-kpi-copy strong {
    display: block;
    margin-top: 7px;
    overflow: hidden;
    color: #0f172a;
    font-size: clamp(1.15rem, 1.45vw, 1.52rem);
    line-height: 1.05;
    font-weight: 950;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.dark-kpi-card.negative .dark-kpi-copy strong {
    color: #dc2626;
}

.dark-kpi-card.positive .dark-kpi-copy strong {
    color: #15803d;
}

.dark-kpi-copy em {
    margin-top: 10px;
    font-size: 0.7rem;
}

.dark-dashboard-home .cb-main-grid,
.dark-dashboard-home .cb-quick-actions-grid {
    display: grid;
    gap: 14px;
}

.dark-dashboard-home .cb-main-grid {
    grid-template-columns: minmax(0, 1.5fr) minmax(260px, 0.75fr);
}

.dark-dashboard-home .cb-panel,
.dark-dashboard-home .cb-quick-actions-panel {
    border: 1px solid rgba(203, 213, 225, 0.88);
    border-radius: 16px;
    background: linear-gradient(180deg, #ffffff, #f8fafc);
    box-shadow: 0 16px 36px rgba(15, 23, 42, 0.07);
}

.dark-dashboard-home .cb-panel-header h2,
.dark-dashboard-home .cb-panel h2 {
    color: #0f172a;
}

.dark-dashboard-home .cb-panel-header p,
.dark-dashboard-home .cb-panel span,
.dark-dashboard-home .cb-panel small {
    color: #64748b;
}

.dark-dashboard-home .cb-chart-mode-button,
.dark-dashboard-home .cb-small-select,
.dark-dashboard-home .cb-outline-button {
    border: 1px solid rgba(203, 213, 225, 0.92);
    background: #ffffff;
    color: #334155;
    box-shadow: 0 8px 18px rgba(15, 23, 42, 0.05);
}

.dark-dashboard-home .cb-area-chart,
.dark-dashboard-home .cb-performance-chart,
.dark-dashboard-home .cb-donut-chart,
.dark-dashboard-home .cb-daily-row,
.dark-dashboard-home .cb-quick-action-card {
    border-color: rgba(203, 213, 225, 0.88);
    background: linear-gradient(180deg, #ffffff, #f8fafc);
    color: #0f172a;
    box-shadow: 0 10px 24px rgba(15, 23, 42, 0.055);
}

.dark-dashboard-home .cb-daily-row strong,
.dark-dashboard-home .cb-donut-legend strong,
.dark-dashboard-home .cb-quick-action-card strong {
    color: #0f172a;
}

.dark-dashboard-home .cb-quick-action-card > span,
.dark-dashboard-home .cb-quick-action-card i {
    background: #eef2f7;
    color: #475569;
}

.dark-dashboard-home .chart-tooltip {
    border: 1px solid rgba(203, 213, 225, 0.92);
    background: #ffffff;
    color: #0f172a;
    box-shadow: 0 18px 36px rgba(15, 23, 42, 0.12);
}

.dark-dashboard-home .chart-tooltip span {
    color: #64748b;
}

.dark-dashboard-home .chart-tooltip strong {
    color: #0f172a;
}

@media (max-width: 1180px) {
    .dark-filter-row,
    .dark-kpi-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .dark-house-row {
        grid-auto-columns: calc((100% - 14px) / 2);
    }

    .dark-filter-actions {
        align-self: end;
    }

    .dark-dashboard-home .cb-main-grid {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 820px) {
    .dark-dashboard-shell {
        grid-template-columns: 1fr;
    }

    .dark-dashboard-sidebar {
        position: relative;
        height: auto;
        min-height: 0;
    }

    .dark-dashboard-main {
        padding: 14px;
    }

    .dark-dashboard-header {
        align-items: stretch;
        flex-direction: column;
    }

    .dark-dashboard-profile {
        min-width: 0;
    }

    .dark-filter-row,
    .dark-kpi-grid {
        grid-template-columns: 1fr;
    }

    .dark-house-row {
        grid-auto-columns: 100%;
    }
}
/* Hide retired sidebar footer cards. */
.dark-dashboard-sidebar .reference-sidebar-footer,
.dark-dashboard-sidebar .reference-sidebar-plan,
.dark-dashboard-sidebar .reference-sidebar-promo {
    display: none !important;
}

/* ===== Dashboard analytics model from reference image ===== */
.dark-dashboard-home .cb-results-model-grid {
    grid-template-columns: minmax(0, 1.95fr) minmax(320px, 1fr) !important;
    gap: 14px !important;
    align-items: stretch !important;
