/* ===== UNIFIED CALENDAR SYSTEM ===== */

:root {
    --cb-calendar-accent: #ef1734;
    --cb-calendar-accent-2: #ff5279;
    --cb-calendar-text: #071332;
    --cb-calendar-muted: #50617d;
    --cb-calendar-border: #cbd8e8;
    --cb-calendar-soft: #f7faff;
}

.reference-period,
.reference-date-field,
.stats-calendar-field,
.tickets-calendar-field,
.movement-extract-calendar-field,
.ticket-form-calendar-field {
    position: relative !important;
    min-width: 0 !important;
}

.reference-period > span,
.reference-date-field > span,
.stats-calendar-field > label,
.tickets-calendar-field > label,
.movement-extract-calendar-field > label,
.ticket-form-calendar-field > label {
    display: block !important;
    margin: 0 0 7px !important;
    color: #31435e !important;
    font-size: 0.78rem !important;
    font-weight: 900 !important;
    line-height: 1.1 !important;
}

.reference-selector-surface,
.reference-date-trigger,
.stats-calendar-button,
.tickets-calendar-button,
.movement-extract-calendar-button,
.ticket-date-top {
    width: 100% !important;
    min-width: 0 !important;
    height: 46px !important;
    min-height: 46px !important;
    display: grid !important;
    grid-template-columns: minmax(0, 1fr) 22px !important;
    align-items: center !important;
    gap: 10px !important;
    border: 1px solid var(--cb-calendar-border) !important;
    border-radius: 10px !important;
    padding: 0 13px !important;
    background: #ffffff !important;
    color: var(--cb-calendar-text) !important;
    font: inherit !important;
    font-size: 0.9rem !important;
    font-weight: 900 !important;
    line-height: 1 !important;
    text-align: left !important;
    box-shadow: 0 1px 0 rgba(15, 23, 42, 0.02) !important;
    cursor: pointer !important;
}

.reference-selector-surface:hover,
.reference-date-trigger:hover,
.stats-calendar-button:hover,
.tickets-calendar-button:hover,
.movement-extract-calendar-button:hover,
.ticket-date-top:hover {
    border-color: #b6c7dc !important;
    background: #fbfdff !important;
}

.reference-selector-surface:focus-visible,
.reference-date-trigger:focus-visible,
.stats-calendar-button:focus-visible,
.tickets-calendar-button:focus-visible,
.movement-extract-calendar-button:focus-visible,
.ticket-date-top:focus-visible {
    outline: 3px solid rgba(239, 23, 52, 0.14) !important;
    outline-offset: 2px !important;
    border-color: rgba(239, 23, 52, 0.45) !important;
}

.reference-selector-value,
.reference-selector-surface input,
.reference-selector-surface select,
.stats-calendar-text,
.tickets-calendar-text {
    min-width: 0 !important;
    overflow: hidden !important;
    color: var(--cb-calendar-text) !important;
    font: inherit !important;
    font-size: 0.9rem !important;
    font-weight: 900 !important;
    line-height: 1.1 !important;
    text-overflow: ellipsis !important;
    white-space: nowrap !important;
}

.reference-selector-surface input,
.reference-selector-surface select {
    border: 0 !important;
    padding: 0 !important;
    background: transparent !important;
    box-shadow: none !important;
    pointer-events: none !important;
}

.reference-calendar-icon,
.stats-calendar-icon,
.ticket-date-icon {
    position: relative !important;
    width: 20px !important;
    height: 20px !important;
    display: inline-grid !important;
    place-items: center !important;
    color: var(--cb-calendar-accent) !important;
    opacity: 1 !important;
    transform: none !important;
    font-size: 0 !important;
    line-height: 1 !important;
}

.reference-calendar-icon {
    fill: none !important;
    stroke: currentColor !important;
    stroke-width: 2.2 !important;
    stroke-linecap: round !important;
    stroke-linejoin: round !important;
}

.stats-calendar-icon::before,
.ticket-date-icon::before {
    content: "" !important;
    width: 16px !important;
    height: 14px !important;
    border: 2px solid currentColor !important;
    border-radius: 4px !important;
    box-sizing: border-box !important;
}

.stats-calendar-icon::after,
.ticket-date-icon::after {
    content: "" !important;
    position: absolute !important;
    top: 4px !important;
    left: 3px !important;
    right: 3px !important;
    height: 2px !important;
    border-radius: 999px !important;
    background: currentColor !important;
}

.reference-calendar-popover,
.stats-calendar-popover,
.tickets-calendar-popover,
.ticket-form-calendar-popover,
.tickets-dynamic-calendar-popover,
.movement-extract-calendar-popover,
.movement-extract-calendar-popover-fixed,
.movement-form-calendar-popover {
    position: absolute !important;
    top: calc(100% + 10px) !important;
    right: 0 !important;
    bottom: auto !important;
    left: auto !important;
    z-index: 300000 !important;
    width: 326px !important;
    max-width: calc(100vw - 42px) !important;
    max-height: calc(100vh - 42px) !important;
    overflow: visible !important;
    border: 1px solid #d6e0ed !important;
    border-radius: 16px !important;
    padding: 14px !important;
    background: #ffffff !important;
    color: var(--cb-calendar-text) !important;
    box-shadow: 0 24px 54px rgba(15, 23, 42, 0.18) !important;
    transform: none !important;
}

.reference-calendar-popover .rdp,
.stats-calendar-popover .rdp,
.tickets-calendar-popover .rdp,
.ticket-form-calendar-popover .rdp,
.tickets-dynamic-calendar-popover .rdp,
.movement-extract-calendar-popover .rdp,
.movement-form-calendar-popover .rdp {
    --rdp-accent-color: var(--cb-calendar-accent) !important;
    --rdp-background-color: rgba(239, 23, 52, 0.1) !important;
    margin: 0 !important;
