/* ===== ControlBet Premium SaaS Design System ===== */
:root {
    --cb-bg: var(--cb-theme-background);
    --cb-bg-soft: var(--cb-theme-surface-secondary);
    --cb-surface: var(--cb-theme-surface);
    --cb-surface-muted: var(--cb-theme-surface-secondary);
    --cb-border: var(--cb-theme-border);
    --cb-border-strong: var(--cb-theme-divider);
    --cb-text: var(--cb-theme-text-primary);
    --cb-text-strong: var(--cb-theme-text-primary);
    --cb-muted: var(--cb-theme-text-muted);
    --cb-muted-strong: var(--cb-theme-text-muted);
    --cb-red: var(--cb-theme-danger);
    --cb-red-dark: var(--cb-theme-primary-hover);
    --cb-green: var(--cb-theme-success);
    --cb-yellow: var(--cb-theme-warning);
    --cb-blue: var(--cb-theme-info);
    --cb-radius-sm: 8px;
    --cb-radius: 12px;
